// 1 Паралипоменон — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Адам, Сиф, Єнос,","Каїнан, Малелеїл, Іаред,","Єнох, Мафусал, Ламех,","Ной, Сим, Хам і Яфет.","Сини Яфета: Гомер, Магог, Мадай, Іаван, [Єлиса,] Фувал, Мешех і Фирас.","Сини Гомера: Аскеназ, Рифат і Фогарма.","Сини Іавана: Єлиса, Фарсис, Киттим і Доданим.","Сини Хама: Хуш, Мицраїм, Фут і Ханаан.","Сини Хуша: Сева, Хавила, Савта, Раама і Савтеха. Сини Раами: Шева і Дедан.","Хуш породив також Нимрода: цей став сильним на землі.","Мицраїм породив: Лудима, Анамима, Легавима, Нафтухима,","Патрусима, Каслухима, від якого пішли филистимляни, і Кафторима.","Ханаан породив Сидона, первістка свого, Хета,","Ієвусея, Аморрея, Гергесея,","Евея, Аркея, Синея,","Арвадея, Цемарея і Хамафея.","Сини Сима: Елам, Ассур, Арфаксад, Луд і Арам. [Сини Арама:] Уц, Хул, Гефер і Мешех.","Арфаксад [породив Каїнана, Каїнан же] породив Салу, Сала ж породив Евера.","У Евера народилися два сини: ім’я одному Фалек, тому що у дні його розділилася земля; ім’я братові його Іоктан.","Іоктан породив Алмодада, Шалефа, Хацармавета, Ієраха,","Гадорама, Узала, Диклу,","Евала, Авимаїла, Шеву,","Офира, Хавилу та Іовава. Усі ці сини Іоктана.","[Сини ж] Симові: Арфаксад, [Каїнан,] Сала,","Евер, Фалек, Рагав,","Серух, Нахор, Фарра,","Аврам, він же Авраам.","Сини Авраама: Ісаак та Ізмаїл.","Ось родовід їх: первісток Ізмаїлів Наваїоф, за ним Кедар, Адбеел, Мивсам,","Мишма, Дума, Масса, Хадад, Фема,","Ієтур, Нафиш і Кедма. Це сини Ізмаїлові.","Сини Хеттури, наложниці Авраамової: вона народила Зимрана, Іокшана, Медана, Мадиана, Ішбака і Шуаха. Сини Іокшана: Шева і Дедан. [Сини Деданові: Рагуїл, Навдеїл, Ассуриїм, Астусиїм і Асомин.]","Сини Мадиана: Ефа, Ефер, Ханох, Авида й Елдага. Всі ці сини Хеттури.","І породив Авраам Ісаака. Сини Ісаака: Ісав та Ізраїль.","Сини Ісава: Елифаз, Рагуїл, Ієус, Ієглом і Корей.","Сини Елифаза: Феман, Омар, Цефо, Гафам, Кеназ; [Фимна ж, наложниця Елифазова, народила йому] Амалика.","Сини Рагуїла: Нахаф, Зерах, Шамма і Миза.","Сини Сеїра: Лотан, Шовал, Цивеон, Ана, Дишон, Ецер і Дишан.","Сини Лотана: Хори і Гемам; а сестра у Лотана: Фимна.","Сини Шовала: Алеан, Манахаф, Евал, Шефо й Онам. Сини Цивеона: Аїа й Ана.","Діти Ани: Дишон [і Оливема, дочка Ани]. Сини Дишона: Хемдан, Ешбан, Іфран і Херан.","Сини Ецера: Билган, Зааван і Акан. Сини Дишана: Уц і Аран.","Ці є царі, які царювали в землі Едома, раніше ніж став цар над синами Ізраїлевими: Бела, син Веора, й ім’я місту його — Дингава;","і помер Бела, і став царем після нього Іовав, син Зераха, з Восори.","І помер Іовав, і став царем після нього Хушам, із землі феманитян.","І помер Хушам, і став царем після нього Гадад, син Бедадів, який уразив мадианитян на полі Моава; ім’я місту його: Авив.","І помер Гадад, і став царем після нього Самла, з Масреки.","І вмер Самла, і став царем після нього Саул з Реховофа, що біля річки.","І помер Саул, і став царем після нього Баал-Ханан, син Ахбора.","І помер Баал-Ханан, і став царем після нього Гадар; ім’я місту його Пау; ім’я дружини його Мегетавеель, дочка Матреда, дочка Мезагава.","І помер Гадар. І були старійшини у Едома: старійшина Фимна, старійшина Алва, старійшина Ієтеф,","старійшина Оливема, старійшина Ела, старійшина Пинон,","старійшина Кеназ, старійшина Феман, старійшина Мивцар,","старійшина Магдиїл, старійшина Ірам. Ось старійшини ідумейські."],"x":{"1":"0.4.25|0.5.3:6","4":"0.9.18","5":"0.10.2","10":"0.10.8","17":"0.10.22|0.11.10","19":"0.10.25|0.11.16","24":"0.11.11","25":"0.11.14","26":"0.11.22:24","27":"0.17.5","28":"0.16.11|0.17.19","29":"0.25.12","32":"0.25.2","33":"0.25.4","34":"0.25.25-26","35":"0.36.10","38":"0.36.20","40":"0.36.23","43":"0.36.31","49":"0.36.38","51":"0.36.40"}},{"v":["Ось сини Ізраїля: Рувим, Симеон, Левій, Іуда, Іссахар, Завулон,","Дан, Йосиф, Веніамін, Неффалим, Гад і Асир.","Сини Іуди: Ір, Онан і Силом, — троє народилися в нього від дочки Шуєвої, хананеянки. І був Ір, первісток Іудин, не благоугодний в очах Господа, і Він умертвив його.","І Фамар, невістка його, народила йому Фареса і Зару. Усіх синів у Іуди було п’ятеро.","Сини Фареса: Есром і Хамул.","Сини Зари: Зимри, Ефан, Еман, Халкол і Дара; усіх їх п’ятеро.","Сини Харми: Ахар, який навів біду на Ізраїля, порушивши закляття.","Син Ефана: Азарія.","Сини Есрома, які народилися в нього: Ієрахмеїл, Арам і Хелувай.","Арам же породив Аминадава; Аминадав породив Наассона, князя синів Іудиних;","Наассон породив Салмона, Салмон породив Вооза;","Вооз породив Овида, Овид породив Ієссея;","Ієссей породив первістка свого Елиава, другого — Аминадава, третього — Самму,","четвертого — Нафанаїла, п’ятого — Раддая,","шостого — Оцема, сьомого — Давида.","Сестри їх: Саруія й Авигея. Сини Саруії: Авесса, Іоав і Азаїл, троє.","Авигея народила Амессу; батько ж Амесси — Ієфер, ізмаїльтянин.","Халев, син Есрома, породив від Азуви, дружини своєї, і від Ієриофи, і ось сини його: Ієшер, Шовав і Ардон.","І померла Азува; і взяв собі Халев [дружину] Ефрафу, і вона народила йому Хура.","Хур породив Урія, Урій породив Веселиїла.","Потім Есром увійшов до дочки Махира, батька Галаадового, і взяв її, будучи шістдесяти років, і вона народила йому Сегува.","Сегув породив Іаїра, і було в нього двадцять три міста в землі Галаадській.","Але гессуряни і сиріяни взяли в них селища Іаїра, Кенаф і залежні від нього міста, — шістдесят міст. Усі ці міста синів Махира, батька Галаадового.","Після смерти Есрома в Халев-Ефрафі дружина Есромова, Авия, народила йому Ашхура, батька Фекої.","Сини Ієрахмеїла, первістка Есромового, були: первісток Рам, за ним Вуна, Орен, Оцем і Ахия.","Була в Ієрахмеїла й інша дружина, ім’я її Афара; вона мати Онама.","Сини Рама, первістка Ієрахмеїлового, були: Маац, Іамин і Екер.","Сини Онама були: Шаммай та Іада. Сини Шаммая: Надав і Авишур.","Ім’я дружини Авишурової Авихаїль, і вона народила йому Ахбана і Молида.","Сини Надава: Селед та Афаїм. І помер Селед бездітним.","Син Афаїма: Іший. Син Ішия: Шешан. Син Шешана: Ахлай.","Сини Іади, брата Шаммаєвого: Ієфер та Іонафан. Ієфер помер бездітним.","Сини Іонафана: Пелеф і Заза. Це сини Ієрахмеїла.","У Шешана не було синів, а тільки дочки. У Шешана був раб, єгиптянин, ім’я його Іарха;","Шешан віддав дочку свою Іархові [рабові своєму] за дружину: і вона народила йому Аттая.","Аттай породив Нафана, Нафан породив Завада;","Завад породив Ефлала, Ефлал породив Овида;","Овид породив Ієуя, Ієуй породив Азарію;","Азарія породив Хелеца, Хелец породив Елеасу;","Елеаса породив Сисмая, Сисмай породив Саллума;","Саллум породив Ієкамію, Ієкамія породив Елишаму.","Сини Халева, брата Ієрахмеїлового: Меша, первісток його, — він батько Зифа; і сини Мареши, батька Хеврона.","Сини Хеврона: Корей і Таппуах, і Рекем і Шема.","Шема породив Рахама, батька Іоркеамового, а Рекем породив Шаммая.","Син Шаммая Маон, а Маон — батько Беф-Цура.","І Ефа, наложниця Халевова, народила Харана, Моцу і Газеза. І Харан породив Газеза.","Сини Ієгдая: Регем, Іофам, Гешан, Пелет, Ефа і Шааф.","Наложниця Халевова, Мааха, народила Шевера і Фирхану;","вона ж народила Шаафа, батька Мадманни, Шеву, батька Махбени і батька Гивеї. Дочка ж Халева — Ахса.","Ось сини Халева: син Хур, первісток Ефрафи; Шовал, батько Кириаф-Іарима;","Салма, батько Вифлеєма; Хареф, батько Бефгадера.","У Шовала, батька Кириаф-Іарима, були сини: Гароє, Хаци, Галменюхот.","Племена Кириаф-Іарима: іфрияни, футияни, шумафани і мидраїтяни. Від цих пішли цоряни й ештаоляни.","Сини Салми: вифлеємляни і нетофафяни, вінець дому Іоавового і половина менухотян — цоряни,","і племена соферійців, які жили в Іабеці, тирейці, шимейці, сухайці: це кинеяни, які пішли від Хамафа, батька Бетрехава."],"x":{"1":"0.29.32","2":"0.35.18:25","3":"0.38.3","4":"12.4.1|0.38.29|50.1.3|7.4.18","7":"5.7.1|5.22.20","10":"7.4.19","15":"50.1.6","50":"5.9.17"}},{"v":["Сини Давида, які народилися в нього в Хевроні, були: первісток Амнон, від Ахиноами ізреелитянки; другий — Далуїя, від Авигеї кармилитянки;","третій — Авессалом, син Маахи, дочки Фалмая, царя Гессурського; четвертий — Адонія, син Аггифи;","п’ятий — Сафатія, від Авитали; шостий — Іфреам, від Аглаї, дружини його, –","шість, які народилися у нього в Хевроні; царював же він там сім років і шість місяців; а тридцять три роки царював у Єрусалимі.","А ці народилися в нього в Єрусалимі: Шима, Шовав, Нафан і Соломон, четверо від Вирсавії, дочки Аммиїлової;","Івхар, Елишама, Елифелет,","Ногаг, Нефег, Іафія,","Елишама, Елиада й Елифелет — дев’ятеро.","Ось усі сини Давида, крім синів від наложниць. Сестра їхня Фамар.","Син Соломона Ровоам; його син Авия, його син Аса, його син Іосафат,","його син Іорам, його син Охозія, його син Іоас,","його син Амасія, його син Азарія, його син Іофам,","його син Ахаз, його син Єзекія, його син Манассія,","його син Амон, його син Іосія.","Сини Іосії: первісток Іоахаз, другий Іоаким, третій Седекія, четвертий Селлум.","Сини Іоакима: Ієхонія, син його; Седекія, син його.","Сини Ієхонії: Асир, Салафиїл, син його;","Малкирам, Федаія, Шенацар, Ієзекія, Гошама і Савадія.","І сини Федаії: Зоровавель і Шимей. Сини ж Зоровавеля: Мешуллам і Хананія, і Шеломиф, сестра їхня,","і ще п’ять: Хашува, Огел, Берехія, Хасадія й Іушав-Хесед.","І сини Хананії: Фелатія та Ісая; його син Рефаія, його син Арнан, його син Овадія, його син Шеханія.","Син Шеханії: Шемаія; сини Шемаії: Хаттуш, Ігеал, Бариах, Неарія і Шафат, шестеро.","Сини Неарії: Елиоенай, Єзекія й Азрикам, троє.","Сини Елиоеная: Годав’ягу, Елеашив, Фелаія, Аккув, Іоханан, Делаія й Анані, семеро."],"x":{"1":"9.3.2","5":"9.5.14","9":"9.13.1","10":"50.1.7","15":"11.23.30:34","16":"50.1.11","19":"14.5.2"}},{"v":["Сини Іуди: Фарес, Есром, Харми, Хур і Шовал.","Реаія, син Шовала, породив Іахафа; Іахаф породив Ахума і Лагада: від них племена цорян.","І ці сини Етама: Ізреель, Ішма та Ідбаш, і сестра їхня, на ім’я Гацлелпоні,","Пенуел, батько Гедора, і Езер, батько Хуша. Ось сини Хура, первістка Ефрафи, батька Вифлеєма.","В Ахшура, батька Фекої, були дві дружини: Хела і Наара.","І народила йому Наара Ахузама, Хефера, Фимні й Ахашфарі; це сини Наари.","Сини Хели: Цереф, Цохар і Ефнан.","Коц породив: Анува і Цовева і племена Ахархела, сина Гарумового.","Іавис був знаменитішим за своїх братів. Мати дала йому ім’я Іавис, сказавши: я народила його з болістю.","І воззвав Іавис до Бога Ізраїлевого і сказав: о, якби Ти благословив мене Твоїм благословенням, розширив наділи мої, і рука Твоя була зі мною, охороняючи мене від зла, щоб я не бідував!.. Бог послав йому, чого він просив.","Хелув же, брат Шухи, породив Махира; він є батьком Ештона.","Ештон породив Беф-Рафу, Пасеаха і Техинну, батька міста Нааса [брата Селома Кенезиїнового й Ахазового]; це жителі Рехи.","Сини Кеназа: Гофониїл і Сераія. Син Гофониїла: Хафаф.","Меонофай породив Офру, а Сераія породив Іоава, родоначальника долини теслярів, тому що вони були теслі.","Сини Халева, сина Ієфонниїного: Ір, Ила і Наам. Син Или: Кеназ.","Сини Ієгаллелела: Зиф, Зифа, Фирія й Асареел.","Сини Езри: Ієфер, Меред, Ефер та Іалон; Ієфер же породив Мерома, Шаммая та Ішбаха, батька Ешфемої.","І дружина його Іудия народила Ієреда, батька Гедора, і Хевера, батька Сохо, й Ієкуфиїла, батька Занаоха. Це сини Биф’ї, дочки фараонової, яку взяв Меред.","Сини дружини його Годії, сестри Нахама, батька Кеїли: Гарми й Ешфемоа — маахатянин.","Сини Симеона: Амнон, Ринна, Бенханан і Филон. Сини Ішия: Зохеф і Бензохеф.","Сини Силома, сина Іудиного: Ір, батько Лехи, і Лаеда, батько Мареші, і родини тих, що виробляли висон, з дому Ашбеї,","й Іоким, і жителі Хозеви, й Іоаш і Сараф, які мали володіння в Моаві, й Іашувилехем; але це події давні.","Вони були гончарі, і жили біля садів і на городах; у царя для робіт його жили вони там.","Сини Симеона: Немуїл, Іамин, Іарив, Зерах і Саул.","Шаллум син його; його син Мивсам; його син Мишма.","Сини Мишми: Хаммуїл, син його; його син Закур; його син Шимей.","У Шимея було шістнадцять синів і шість дочок; у братів же його синів було небагато, і все плем’я їх не таке було численне, як плем’я синів Іуди.","Вони жили у Вирсавії, Моладі, Хацаршуалі,","у Билзі, в Ецемі, у Фоладі,","у Вефуїлі, у Хормі, в Циклагу,","у Беф-Маркавофі, у Хацарсусимі, у Беф-Биреї й у Шааримі. Ось міста їхні до царювання Давида,","із селами їх: Етам, Аїн, Риммон, Фокен і Ашан, — п’ять міст.","І всі селища їхні, що знаходилися навколо цих міст до Ваала; ось місця проживання їхнього і родоводу їхнього.","Мешовав, Іамлех та Іосія, син Амассії,","Іоїл та Ієгу, син Іошиви, сина Сераії, сина Асиїлового,","Елиоенай, Якова, Ішохаія, Асаія, Адиїл, Ішимиїл і Ванея,","і Зиза, син Шифія, син Аллона, син Ієдаії, син Шимрія, син Шемаії.","Ці пойменовані були князями племен своїх, і дім батьків їхніх розділився і розмножився.","Вони доходили до Герари і до східного боку долини, щоб знайти пасовища для стад своїх;","і знайшли пасовища плідні і добрі і землю обширну, спокійну і безпечну, тому що до них жило там тільки небагато хамитян.","І прийшли ці, за іменами записані, у дні Єзекії, царя Юдейського, і перебили кочівників і осілих, які там знаходилися, і знищили їх назавжди й оселилися на місці їх, тому що там були пасовища для стад їхніх.","Із них же, із синів Симеонових, пішли до гори Сеїр п’ятсот чоловік: Фелатія, Неарія, Рефаія й Узиїл, сини Ішия, були на чолі їх;","і побили залишок амаликитян, які вціліли там, і живуть там до цього дня."],"x":{"1":"12.2.4|0.38.29|0.46.12","24":"0.46.10|1.6.15"}},{"v":["Сини Рувима, первістка Ізраїлевого, — він первісток; але, коли осквернив він постіль батька свого, первородство його віддане синам Йосифа, сина Ізраїлевого, з тим однак же, щоб не писатися їм первородними;","тому що Іуда був найсильнішим із братів своїх, і вождь від нього, але першість перенесена на Йосифа.","Сини Рувима, первістка Ізраїлевого: Ханох, Фаллу, Хецрон і Харми.","Сини Іоїля: Шемая, син його; його син Гог, його син Шимей,","його син Миха, його син Реаія, його син Ваал,","його син Беера, якого відвів у полон Феглафелласар, цар Ассирійський. Він був князем рувимлян.","І брати його, за племенами їх, за родовідним списком їх, були: головний Ієїель, потім Захарія,","і Бела, син Азаза, сина Шеми, сина Іоїля. Він жив в Ароері до Нево і Ваал-Меона;","а на сход він жив до входу в пустелю, що йде від ріки Євфрату, тому що стада їх були численні в землі Галаадській.","У дні Саула вони вели війну з агарянами, які впали від рук їх, а вони стали жити в наметах і по всьому східному боці Галаада.","Сини Гада жили навпроти них у землі Васанській до Салхи:","у Васані Іоїль був головний, Шафан другий, потім Іаанай і Шафат.","Братів їхніх з родинами їхніми було сім: Михаїл, Мешуллам, Шева, Іорай, Іаакан, Зия та Евер.","Ось сини Авихаїла, сина Хурія, сина Іароаха, сина Галаада, сина Михаїла, сина Ієшишая, сина Іахдо, сина Буза.","Ахи, син Авдиїла, сина Гунієвого, був главою свого роду.","Вони жили в Галааді, у Васані й у залежних від нього містах і у всіх околицях Сарона, до виходу їх.","Усі вони перераховані у дні Іоафама, царя Юдейського, й у дні Ієровоама, царя Ізраїльського.","У нащадків Рувима і Гада і половини племені Манассіїного було людей войовничих, чоловіків, які носять щит і меч, які стріляють з лука і навчені до битви, сорок чотири тисячі сімсот шістдесят, які виходять на війну.","І воювали вони з агарянами, Ієтуром, Нафишем і Надавом.","І надана була їм допомога проти них, і віддані були в руки їхні агаряни й усе, що в них було, тому що вони під час битви воззвали до Бога, і Він почув їх, за те, що вони уповали на Нього.","І взяли вони стада їхні: верблюдів п’ятдесят тисяч, із дрібної худоби двісті п’ятдесят тисяч, ослів дві тисячі, і сто тисяч душ людей,","тому що багато впало убитими, оскільки від Бога була битва ця. І жили вони на місці їхньому до переселення.","Нащадки половини коліна Манассіїного жили в тій землі, від Васана до Ваал-Ермона і Сенира і до гори Ермона; і їх було багато.","І ось глави поколінь їх: Ефер, Іш’ї, Елиїл, Азриїл, Єремія, Годавія й Іагдиїл, мужі могутні, мужі вельможні, глави родів своїх.","Але коли вони згрішили проти Бога батьків своїх і стали блудно ходити услід богам народів тієї землі, яких вигнав Бог від лиця їх,","тоді Бог Ізраїлів збудив дух Фула, царя Ассирійського, і дух Феглафелласара, царя Ассирійського, і він виселив рувимлян і гадитян і половину коліна Манассіїного, і відвів їх у Халах, і Хавор, і Ару, і на ріку Гозан, — де вони до цього дня."],"x":{"1":"0.35.22-23|0.46.8|0.49.3-4|1.6.14|3.26.5","2":"0.49.10","3":"0.46.9|1.6.14","6":"11.15.29","10":"25.82.7","11":"5.13.24","16":"31.33.9","17":"11.15.7","19":"0.25.15","20":"1.17.11|21.4.10|25.144.19","22":"8.17.3","23":"4.3.9","25":"11.17.7","26":"11.15.29"}},{"v":["Сини Левія: Гирсон, Каафран і Мерарі.","Сини Каафа: Амрам, Іцгар, Хеврон та Узиїл.","Діти Амрама: Аарон, Мойсей і Маріам. Сини Аарона: Надав, Авиуд, Єлеазар і Іфамар.","Єлеазар породив Финеєса, Финеєс породив Авишуя;","Авишуй породив Буккія, Буккій породив Озію;","Озія породив Зерахію, Зерахія породив Мераїофа;","Мераїоф породив Амарію, Амарія породив Ахитува;","Ахитув породив Садока, Садок породив Ахимааса;","Ахимаас породив Азарію, Азарія породив Іоанана;","Іоанан породив Азарію, — це той, який був священиком у храмі, побудованому Соломоном в Єрусалимі.","І породив Азарія Амарію, Амарія породив Ахитува;","Ахитув породив Садока, Садок породив Селлума;","Селлум породив Хелкію, Хелкія породив Азарію;","Азарія породив Сераію, Сераія породив Іоседека.","Іоседек пішов у полон, коли Господь переселив юдеїв і єрусалимлян рукою Навуходоносора.","Отже, сини Левія: Гирсон, Кааф і Мерарі.","Ось імена синів Гирсонових: Ливні і Шимей.","Сини Каафа: Амрам, Іцгар, Хеврон та Узиїл.","Сини Мерарі: Махли і Муши. Ось нащадки Левія за родами їх.","У Гирсона: Ливні, син його; Іахав, син його; Зимма, син його;","Іоах, син його; Іддо, син його; Зерах, син його; Ієафрай, син його.","Сини Каафа: Аминадав, син його; Корей, син його; Асир, син його;","Елкана, син його; Евиасаф, син його; Асир, син його;","Тахаф, син його; Уриїл, син його; Узія, син його; Саул, син його.","Сини Елкани: Амасай і Ахимоф.","Елкана, син його; Цофай, син його; Нахаф, син його;","Елиаф, син його; Ієрохам, син його, Елкана, син його; [Самуїл, син його].","Сини Самуїла: первісток Іоїль, другий Авия.","Сини Мерарі: Махли; Ливні, син його; Шимей, син його; Уза, син його;","Шима, син його; Хаггія, син його; Асаія, син його.","Ось ті, яких Давид поставив начальниками над співцями в домі Господньому, з часу поставлення в ньому ковчега.","Вони служили співцями перед скинією зібрання, доки Соломон не побудував дому Господнього в Єрусалимі. І вони ставали на службу свою за уставом своїм.","Ось ті, які ставали із синами своїми: із синів Каафових — Еман співець, син Іоїля, син Самуїла,","син Елкани, син Ієрохама, син Елиїла, син Тоаха,","син Цуфа, син Елкани, син Махафа, син Амасая,","син Елкани, син Іоїля, син Азарії, син Цефанії,","син Тахафа, син Асира, син Авиасафа, син Корея,","син Іцгара, син Каафа, син Левія, син Ізраїля;","і брат його Асаф, який стояв праворуч від нього, — Асаф, син Берехії, син Шими,","син Михаїла, син Ваасеї, син Малхиї,","син Ефнія, син Зераха, син Адаії,","син Ефана, син Зимми, син Шимія,","син Іахафа, син Гирсона, син Левія.","А із синів Мерарі, братів їхніх, — на лівому боці: Ефан, син Кишія, син Авдія, син Маллуха,","син Хашавії, син Амасії, син Хелкії,","син Амція, син Ванія, син Шемера,","син Махлія, син Мушія, син Мерарі, син Левія.","Брати їхні левити визначені на всякі служби при домі Божому;","Аарон же і сини його спалювали на жертовнику всепалення і на жертовнику кадильному, і звершували всяке священнодійство у Святому Святих і для очищення Ізраїля в усьому, як заповів раб Божий Мойсей.","Ось сини Аарона: Єлеазар, син його; Финеєс, син його; Авиуд, син його;","Буккій, син його; Уззій, син його; Зерахія, син його;","Мераїоф, син його; Амарія, син його; Ахитув, син його;","Садок, син його; Ахимаас, син його.","І ось оселі їхні за селищами їхніми у наділах їхніх: синам Аарона з племені Каафового, оскільки жереб випав їм,","дали Хеврон, у землі Іудиній, і передмістя його навколо нього;","поля ж цього міста і села його віддали Халеву, синові Ієфонніїному.","Синам Аарона дали також міста притулків: Хеврон і Ливну з їх передмістями, Іаттир та Ештемоа і передмістя його,","і Хилен і передмістя його, Давир і передмістя його,","і Ашан і передмістя його, Вефсамис і передмістя його,","а від коліна Веніамінового — Геву і передмістя її, і Аллемеф і передмістя його, і Анафоф і передмістя його: усіх міст їхніх у племенах їхніх тринадцять міст.","Решті синів Каафа, із родин цього коліна, дано за жеребом десять міст із наділу половини коліна Манассіїного.","Синам Гирсона за племенами їхніми, від коліна Іссахарового, і від коліна Асирового, і від коліна Неффалимового, і від коліна Манассіїного у Васані, дано тринадцять міст.","Синам Мерарі за племенами їхніми, від коліна Рувимового, і від коліна Гадового, і від коліна Завулонового, дано за жеребом дванадцять міст.","Так дали сини Ізраїлеві левитам міста і передмістя їх.","Дали вони за жеребом від коліна синів Іудиних, і від коліна синів Симеонових, і від коліна синів Веніамінових ті міста, які вони назвали на імення.","Деяким же племенам синів Каафових дали міста від коліна Єфремового.","І дали їм міста притулків: Сихем і передмістя його на горі Єфремовій, і Гезер і передмістя його,","Іокмеам і передмістя його, і Беф-Орон і передмістя його,","й Аїалон і передмістя його, і Гаф-Риммон і передмістя його;","від половини коліна Манассіїного — Анер і передмістя його, Білеам і передмістя його. Це поколінню решти синів Каафових.","Синам Гирсона від племені половини коліна Манассіїного дали Голан у Васані і передмістя його, й Аштароф і передмістя його.","Від коліна Іссахарового — Кедес і передмістя його, Давраф і передмістя його,","і Рамоф і передмістя його, й Анем і передмістя його;","від коліна Асирового — Машал і передмістя його, й Авдон і передмістя його,","і Хуком і передмістя його, і Рехов і передмістя його;","від коліна Неффалимового — Кедес у Галилеї і передмістя його, і Хаммон і передмістя його, і Кириафаїм і передмістя його.","А іншим синам Мерариним — від коліна Завулонового Риммон і передмістя його, Фавор і передмістя його.","По той бік Йордану, навпроти Єрихона, на схід від Йордану, від коліна Рувимового дали Восор у пустелі і передмістя його, й Іаацу і передмістя її,","і Кедемоф і передмістя його, і Мефааф і передмістя його;","від коліна Гадового — Рамоф у Галааді і передмістя його, і Маханаїм і передмістя його,","й Елевон і передмістя його, і Іазер та передмістя його."],"x":{"1":"12.23.6|0.46.11|1.6.16|3.3.17|3.26.57","3":"1.6.20","4":"1.6.25|1.28.1","6":"14.7.3","8":"9.8.17","13":"11.22.4","14":"11.25.18|14.7.1|32.52.24","16":"1.6.16","18":"1.6.18|12.23.12","22":"1.6.24","27":"8.1.1","28":"8.8.2","33":"12.15.17","39":"12.15.17","44":"12.15.17","54":"5.21.10","57":"5.21.13","67":"5.21.21"}},{"v":["Сини Іссахара: Фола, Фуа, Іашув і Шимрон, четверо.","Сини Фоли: Уззій, Рефаія, Ієриїл, Іахмай, Івсам і Самуїл, глави в поколіннях Фоли, люди войовничі у своїх поколіннях; число їх у дні Давида було двадцять дві тисячі і шістсот.","Син Уззія: Ізрахія; а сини Ізрахії: Михаїл, Овадіа, Іоїль та Ішшія, п’ятеро. Усі вони глави.","У них, за родами їхніми, за поколіннями їхніми, було готового до битви війська тридцять шість тисяч; тому що в них було багато дружин і синів.","Братів же їхніх, у всіх поколіннях Іссахарових, людей войовничих, було вісімдесят сім тисяч, яких внесли до родовідних записів.","У Веніаміна: Бела, Бехер та Ієдиаїл, троє.","Сини Бели: Ецбон, Уззій, Уззиїл, Ієримоф і Іри, п’ятеро, глави поколінь, люди войовничі. У родовідних списках записано їх двадцять дві тисячі тридцять чотири.","Сини Бехера: Земира, Іоаш, Єлиєзер, Елиоенай, Омри, Іремоф, Авия, Анафоф і Алемеф: усі ці сини Бехера.","В родовідних списках записано їх за родами їхніми, за главами поколінь, людей войовничих — двадцять тисяч і двісті.","Син Ієдиаїла: Билган. Сини Билгана: Ієус, Веніамін, Егуд, Хенаана, Зефан, Фарсис і Ахишахар.","Усі ці сини Ієдиаїла були главами поколінь, люди войовничі; сімнадцять тисяч і двісті було тих, що ходили на війну.","І Шупим і Хупим, сини Іра; Хушим, син Ахера;","сини Неффалима: Іахцеїл, Гуні, Ієцер і Шиллем, діти Валли.","Сини Манассії: Асриїл, якого народила наложниця його арамеянка; вона ж народила Махира, батька Галаадового.","Махир взяв за дружину сестру Хупима і Шупима, — ім’я сестри їхньої Мааха; ім’я другому Салпаад. У Салпаада були тільки дочки.","Мааха, дружина Махирова, народила сина і нарекла йому ім’я Кереш, а ім’я братові його Шереш. Сини його: Улам і Рекем.","Син Улама: Бедан. Ось сини Галаада, сина Махира, сина Манассіїного.","Сестра його Молехеф народила Ішгода, Авиєзера і Махлу.","Сини Шемиди були: Ахиан, Шехем, Ликхи й Аниам.","Сини Єфрема: Шутелах, і Беред, син його, і Фахаф, син його, й Елеада, син його, і Фахаф, син його,","і Завад, син його, і Шутелах, син його, й Езер і Елеад. І убили їх жителі Гефа, уродженці тієї землі, за те, що вони пішли захопити стада їхні.","І плакав за ними Єфрем, батько їхній, багато днів, і приходили брати його утішати його.","Потім він увійшов до дружини своєї, і вона зачала і народила сина, і він нарік йому ім’я: Берія, тому що біда осягла дім його.","І дочка в нього була Шеера. Вона побудувала Беф-Орон нижній і верхній і Уззен-Шееру.","І Рефай, син його, і Решеф, і Фелах, син його, і Фахан, син його,","Лаедан, син його, Аммиуд, син його, Елишама, син його,","Нон, син його, Ісус, син його.","Володіння їхні і місця проживання їхні були: Вефиль і залежні від нього міста; на схід Нааран, на захід Гезер і залежні від нього міста; Сихем і залежні від нього міста до Гази і залежних від неї міст.","А з боку синів Манассіїних: Беф-Сан і залежні від нього міста, Фаанах і залежні від нього міста, Мегиддо і залежні від нього міста, Дор і залежні від нього міста. В них жили сини Йосифа, сина Ізраїлевого.","Сини Асира: Імна, Ішва, Ішви і Берія, і сестра їхня Серах.","Сини Берії: Хевер і Малхиїл. Він батько Бирзаїфа.","Хевер породив Іафлета, Шомера і Хофама, і Шую, сестру їхню.","Сини Іафлета: Пасах, Бимгал і Ашваф. Ось сини Іафлета.","Сини Шемера: Ахи, Рохга, Іхубба й Арам.","Сини Гелема, брата його: Цофах, Імна, Шелеш і Амал.","Сини Цофаха: Суах, Харнефер, Шуал, Бері, Імра,","Бецер, Год, Шамма, Шилша, Іфран і Беера.","Сини Ієфера: Ієфунні, Фиспа й Ара.","Сини Улли: Арах, Ханниїл і Риція.","Всі ці сини Асира, глави поколінь, люди добірні, войовничі, головні начальники. Записано у них у родовідних списках у війську, для війни, за рахунком двадцять шість тисяч чоловік."],"x":{"1":"0.46.13","6":"12.8.1|0.46.21","12":"0.46.21|3.26.42","13":"0.46.24","14":"3.26.29|5.17.1","15":"3.26.33|3.27.1","20":"3.26.35","28":"5.16.1|0.48.22","29":"5.17.11","30":"0.46.17"}},{"v":["Веніамін породив Белу, первістка свого, другого Ашбела, третього Ахрая,","четвертого Ноху і п’ятого Рафу.","Сини Бели були: Аддар, Гера, Авиуд,","Авишуа, Нааман, Ахоах,","Гера, Шефуфан і Хурам.","І ось сини Егуда, що були главами родів, які жили в Геві і переселені у Манахаф:","Нааман, Ахия і Гера, який переселив їх; він породив Уззу й Ахихуда.","Шегараїм породив дітей у землі Моавитській після того, як відпустив від себе Хушиму і Баару, дружин своїх.","І породив він від Ходеші, дружини своєї, Іовава, Цивію, Мешу, Малхама,","Ієуца, Шахию і Мирму: ось сини його, глави поколінь.","Від Хушими породив він Авитува й Елпаала.","Сини Елпаала: Евер, Мишам і Шемер, який побудував Оно і Лод і залежні від нього міста, –","і Берія і Шема. Вони були главами поколінь жителів Аїалона. Вони вигнали жителів Гефа.","Ахио, Шашак, Іремоф,","Зевадія, Арад, Едер,","Михаїл, Ішфа та Іоха — сини Берії.","Зевадія, Мешуллам, Хизкій, Хевер,","Ішмерай, Ізлія та Іовав — сини Елпаала.","Іаким, Зихрій, Завдій,","Елиєнай, Цилфай, Елиїл,","Адаія, Бераія і Шимраф — сини Шимея.","Ішпан, Евер, Елиїл,","Авдон, Зихрій, Ханан,","Хананія, Елам, Антофія,","Іфдія і Фенуїл — сини Шашака.","Шамшерай, Шехарія, Афалія,","Іаарешія, Елія і Зихрій, сини Ієрохама.","Це глави поколінь, у родах своїх головні. Вони жили в Єрусалимі.","В Гаваоні жили: [Ієїл,] батько гаваонитян, — ім’я дружини його Мааха, –","і син його, первісток Авдон, за ним Цур, Кис, Ваал, Надав, [Нер,]","Гедор, Ахио, Зехер і Миклоф.","Миклоф породив Шимея. І вони жили поруч з братами своїми в Єрусалимі, разом із братами своїми.","Нер породив Киса; Кис породив Саула; Саул породив Іонафана, Мелхисуя, Авинадава й Ешбаала.","Син Іонафана Мериббаал; Мериббаал породив Миху.","Сини Михи: Пифон, Мелег, Фаарея й Ахаз.","Ахаз породив Іоїадду; Іоїадда породив Алемефа, Азмавефа і Замврія; Замврій породив Моцу;","Моца породив Бинею. Рефаія, син його; Елеаса, син його; Ацел, син його.","В Ацела шість синів, і ось імена їхні: Азрикам, Бохру, Ісмаїл, Шеарія, Овадія і Ханан; усі вони сини Ацела.","Сини Ешека, брата його: Улам, первісток його, другий Ієуш, третій Елифелет.","Сини Улама були люди войовничі, які стріляли з лука, мали багато синів і онуків: сто п’ятдесят. Усі вони від синів Веніаміна."],"x":{"1":"12.7.6|0.46.21","6":"8.11.4","12":"17.11.35","13":"5.19.42","29":"12.9.35","32":"12.9.38","33":"12.9.39|8.14.51","34":"9.4.4"}},{"v":["Так були перераховані за родами своїми всі ізраїльтяни, і ось вони записані в книзі царів ізраїльських. Юдеї ж за беззаконня свої переселені у Вавилон.","Перші жителі, які жили у володіннях своїх, по містах ізраїльських, були ізраїльтяни, священики, левити і нефинеї.","В Єрусалимі жили деякі із синів Іудиних і із синів Веніамінових, і із синів Єфремових і Манассіїних:","Уфай, син Аммиуда, син Омри, син Імрія, син Ванія, — із синів Фареса, сина Іудиного;","із синів Шилона — Асаія первісток і сини його;","із синів Зари — Ієуїл і брати їхні, — шістсот дев’яносто;","з синів Веніамінових Саллу, син Мешуллама, син Годавії, син Гассенуї;","та Івнія, син Ієрохама, і Ела, син Уззія, сина Михриєвого, і Мешуллам, син Шефатії, сина Регуїла, сина Івнії,","і брати їхні, за родами їхніми: дев’ятсот п’ятдесят шість, — усі ці мужі були глави родів у поколіннях своїх.","А зі священиків: Ієдаія, Іоїарив, Іахин,","й Азарія, син Хелкії, син Мешуллама, син Садока, син Мераїофа, син Ахитува, який начальствує у домі Божому;","і Адаія, син Ієрохама, син Пашхура, син Малхії; і Маасай, син Адиела, син Іахзера, син Мешуллама, син Мешиллемифа, син Іммера;","і брати їхні, глави родів своїх: тисяча сімсот шістдесят, — люди відмінні у справі служіння в домі Божому.","А з левитів: Шемаія, син Хашува, син Азрикама, син Хашавії, — із синів Мерариних;","і Вакбакар, Хереш, Галал, і Матфанія, син Михи, син Зихрія, син Асафа;","й Овадія, син Шемаії, син Галала, син Ідифуна, і Берехія, син Аси, син Елкани, що жив у селищах нетофафських.","А воротарі: Шаллум, Аккуб, Талмон і Ахиман, і брати їхні; Шаллум був головним.","І донині ці воротарі біля воріт царських, на схід, утримують варту синів Левіїних.","Шаллум, син Коре, син Евиасафа, син Корея, і брати його з роду його, кореяни, у справі служіння свого, були зі сторожею біля порогів скинії, а батьки їхні охороняли вхід у стан Господній.","Финеєс, син Єлеазарів, був раніше начальником над ними, і Господь був з ним.","Захарія, син Мешелемії, був воротарем біля дверей скинії зібрання.","Усіх їх, обраних у воротарі до порогів, було двісті дванадцять. Вони внесені в список за селищами своїми. Їх поставив Давид і Самуїл прозорливець за вірність їх.","І вони і сини їхні були на варті біля воріт дому Господнього, при домі скинії.","На чотирьох боках знаходилися воротарі: на східному, західному, північному і південному.","Брати ж їхні жили в селищах своїх, приходячи до них час від часу на сім днів.","Ці чотири начальники воротарів, левити, були в довірі; вони ж були приставлені до осель і до скарбів дому Божого.","Навколо дому Божого вони і ніч проводили, тому що на них лежала охорона, і вони повинні були щоранку відмикати двері.","Одні з них були приставлені до службових сосудів, так що за рахунком приймали їх і за рахунком видавали.","Іншим з них було доручено інше начиння й усі священні потреби: борошно краще, і вино, і єлей, і ладан, і пахощі.","А із синів священичих деякі готували миро з речовин запашних.","Маттафії з левитів, — він первісток Селлума кореянина, — довірено було те, що готується на сковородах.","Деяким із братів їхніх, із синів Каафових, було доручено заготівлю хлібів предкладення, щоб приносити їх щосуботи.","Співці ж, головні в поколіннях левитських, у кімнатах храму були вільні від занять, тому що день і ніч вони зобов’язані були займатися мистецтвом своїм.","Це глави поколінь левитських, у родах своїх головні. Вони жили в Єрусалимі.","У Гаваоні жили: батько гаваонитян Ієїл, — ім’я дружини його Мааха,","і син його первісток Авдон, за ним Цур, Кис, Ваал, Нер, Надав,","Гедор, Ахио, Захарія і Миклоф.","Миклоф породив Шимеама. І вони жили поряд з братами своїми в Єрусалимі разом з братами своїми.","Нер породив Киса, Кис породив Саула, Саул породив Іонафана, Мелхисуя, Авинадава й Ешбаала.","Син Іонафана Мериббаал; Мериббаал породив Миху.","Сини Михи: Пифон, Мелех, Фарей [і Ахаз].","Ахаз породив Іаеру; Іаера породив Алемефа, Азмавефа і Замврія; Замврій породив Моцу;","Моца породив Бинею: Рефаія, син його; Елеаса, син його; Ацел, син його.","У Ацела шість синів, і ось імена їхні: Азрикам, Бохру, Ісмаїл, Шеарія, Овадія і Ханан. Це сини Ацела."],"x":{"1":"11.24.15","2":"17.11.3","11":"11.22.8","18":"11.16.18|36.46.1","19":"25.41.1","20":"3.25.11","22":"25.83.11|8.9.11","30":"1.30.34","31":"2.2.5","32":"1.25.30","35":"12.8.29","38":"12.8.32","39":"12.8.33","41":"12.8.35","44":"12.8.38"}},{"v":["Филистимляни воювали з Ізраїлем, і побігли ізраїльтяни від филистимлян, і падали уражені на горі Гелвуї.","І погналися филистимляни за Саулом і синами його, й убили филистимляни Іонафана й Авинадава і Мелхисуя, синів Саулових.","Битва проти Саула посилилася, і стрільці кинулися на нього, так що він зранений був стрільцями.","І сказав Саул зброєносцеві своєму: вийми меч твій і заколи мене ним, щоб не прийшли ці необрізані і не наглумилися з мене. Але зброєносець не наважився, тому що дуже злякався. Тоді Саул узяв меч і упав на нього.","Зброєносець його, побачивши, що Саул помер, і сам упав на меч і помер.","І вмер Саул, і три сини його, і весь дім його разом з ним помер.","Коли побачили ізраїльтяни, які були в долині, що усі біжать і що Саул і сини його померли, то залишили міста свої і розбіглися; а филистимляни прийшли й оселилися в них.","На другий день прийшли филистимляни оббирати вбитих, і знайшли Саула і синів його, які впали на горі Гелвуйській,","і роздягли його, і зняли з нього голову його і зброю його, і послали по землі Филистимській, щоб сповістити про це перед ідолами їхніми і перед народом.","І поклали зброю його в капищі богів своїх, і голову його встромили в домі Дагона.","І почув весь Іавис галаадський усе, що зробили филистимляни із Саулом.","І піднялися всі люди сильні, взяли тіло Саулове і тіла синів його, і принесли їх в Іавис, і поховали кістки їхні під дубом в Іависі, і постилися сім днів.","Так помер Саул за своє беззаконня, яке він учинив перед Господом, за те, що не дотримався слова Господнього і звернувся до чарівниці з запитанням,","а не звертався до Господа. За те Він і умертвив його, і передав царство Давиду, синові Ієссеєвому."],"x":{"1":"8.31.1","4":"8.31.4|6.9.54","7":"8.31.7","10":"8.31.10","11":"6.21.8|8.31.11","12":"8.31.13|9.2.5","13":"8.15.23","14":"8.16.13|9.12.7"}},{"v":["І зібралися всі ізраїльтяни до Давида в Хеврон і сказали: ось, ми кость твоя і плоть твоя;","і вчора, і третього дня, коли ще Саул був царем, ти виводив і вводив Ізраїля, і Господь Бог твій сказав тобі: «ти будеш пасти народ Мій, Ізраїля, і ти будеш вождем народу Мого, Ізраїля».","І прийшли усі старійшини Ізраїлеві до царя в Хеврон, і уклав з ними Давид завіт у Хевроні перед лицем Господнім; і вони помазали Давида на царя над Ізраїлем, за словом Господнім, через Самуїла.","І пішов Давид і весь Ізраїль до Єрусалима, тобто до Ієвуса. А там були ієвусеї, жителі тієї землі.","І сказали жителі Ієвуса Давиду: не ввійдеш сюди. Але Давид узяв фортецю Сион; це місто Давидове.","І сказав Давид: хто раніше за усіх вразить ієвусеїв, той буде главою і воєначальником. І зійшов раніше за всіх Іоав, син Саруї, і став главою.","Давид жив у тій фортеці, тому і називали її містом Давидовим.","І він оббудував місто навкруги, починаючи від Милло, всю околицю, а Іоав відновив інші частини міста.","І процвітав Давид, і піднімався більше і більше, і Господь Саваоф був з ним.","Ось головні із сильних у Давида, які спільно подвизалися з ним у царстві його, разом з усім Ізраїлем, щоб поставити його царем, за словом Господнім, над Ізраїлем,","і ось число хоробрих, які були у Давида: Ієсваал, син Ахамані, головний з тридцяти. Він підняв спис свій на триста чоловік і вразив їх за один раз.","Після нього Єлеазар, син Додо ахохиянина, з трьох хоробрих:","він був з Давидом у Фасдамимі, куди филистимляни зібралися на війну. Там частина поля була засіяна ячменем, і народ побіг від филистимлян;","але вони стали серед поля, зберегли його й уразили филистимлян. І дарував Господь спасіння велике!","Троє цих головних з тридцяти вождів зійшли на скелю до Давида, у печеру Одоллам, коли стан филистимлян був розташований у долині рефаїмів.","Давид тоді був в укріпленому місці, а охоронне військо филистимлян було тоді у Вифлеємі.","І дуже захотілося пити Давиду, і він сказав: хто напоїть мене водою з колодязя вифлеємського, що біля воріт?","Тоді ці троє пробилися крізь стан филистимський і почерпнули води з колодязя вифлеємського, що біля воріт, і взяли, і принесли Давиду. Але Давид не захотів пити її і вилив її у славу Господа,","і сказав: збережи мене Господь, щоб я зробив це! Чи стану я пити кров мужів цих, які покладали душі свої! Бо з небезпекою для власного життя вони принесли воду. І не захотів пити її. Ось що зробили троє цих хоробрих.","І Авесса, брат Іоава, був головним із трьох: він убив списом своїм триста чоловік, і був у славі у тих трьох.","Із трьох він був найзнатнішим і був начальником; але з тими трьома не рівнявся.","Ванея, син Іодая, мужа хороброго, великий за ділами, з Кавцеїла: він вразив двох Ариїлів моавитських; він же зійшов і убив лева у рові, в сніжний час;","він же убив єгиптянина, людину на зріст у п’ять ліктів: у руці єгиптянина був спис, як навій у ткачів, а він підійшов до нього з палкою і, вирвавши спис з руки єгиптянина, убив його його ж списом:","ось що зробив Ванея, син Іодая. І він був у славі у тих трьох хоробрих;","він був знатнішим тридцяти, але з трьома не рівнявся, і Давид поставив його найближчим виконавцем своїх наказів.","А головні з воїнів: Асаїл, брат Іоава; Елханан, син Додо, з Вифлеєма;","Шамма гародитянин; Херец пелонитянин;","Іра, син Ікеша, фекоїтянин; Евиезер анафофянин;","Сивхай хушатянин; Ілай ахохиянин;","Магарай нетофафянин; Хелед, син Ваани, нетофафянин;","Іттай, син Рибая, з Гиви Веніамінової; Ванея пирафонянин;","Хурай з Наголе-Гааша; Авиел з Арави;","Азмавеф бахарумиянин; Елияхба шаалбонянин.","Сини Гашема гизонитянина: Іонафан, син Шаге, гараритянин;","Ахиам, син Сахара, гараритянин; Елифал, син Ури;","Хефер з Махери; Ахия пелонитянин;","Хецрой кармилитянин; Наарай, син Езбая;","Іоїль, брат Нафана; Мивхар, син Гагрія;","Целек аммонитянин; Нахарай берофянин, зброєносець Іоава, сина Саруї;","Іра іфриянин; Гареб іфриянин;","Урія хеттеянин; Завад, син Ахлая;","Адина, син Шизи, рувимлянин, глава рувимлян, і в нього було тридцять;","Ханан, син Маахи; Іосафат мифниянин;","Уззія аштерофянин; Шама та Іеїел, сини Хофама ароерянина;","Ієдиаел, син Шимрія, та Іоха, брат його, фициянин;","Елиел з Махавима, та Ієривай і Іошавія, сини Елнаама, й Іфма моавитянин;","Елиел, Овед та Іасиел з Мецоваї."],"x":{"1":"9.5.1","2":"8.16.13|25.77.71","3":"12.12.38|8.16.13","4":"9.5.6","6":"9.5.8","9":"9.5.10","10":"9.23.8","11":"9.23.8","12":"9.23.9","14":"9.23.12","17":"9.23.15","20":"9.23.18","21":"9.23.19","22":"9.23.20","23":"8.17.7","25":"9.23.23","26":"9.23.24","30":"9.23.28","41":"9.11.3"}},{"v":["І ці також прийшли до Давида в Секелаг, коли він ще ховався від Саула, сина Кисового, і були серед хоробрих, які допомагали в битві.","Озброєні луком, вони правою і лівою рукою кидали камені, і стріляли стрілами з лука, — з братів Саула, від Веніаміна;","головний Ахиєзер, за ним Іоас, сини Шемаї, з Гиви; Ієзиел і Фелет, сини Азмавефа; Бераха та Ієгу з Анафофа;","Ішмаія гаваонитянин, хоробрий з тридцяти і начальник над тридцятьма; Єремія, Іахазиїл, Іоханан та Іозавад з Гедери.","Елузай, Ієримоф, Веалія, Шемарія, Сафатія харифиянин;","Елкана, Ішшияху, Азариїл, Іоезер та Іошавам, кореяни;","й Іоела і Зевадія, сини Ієрохама, з Гедора.","І з гадитян перейшли до Давида в укріплення, у пустелю, люди мужні, войовничі, озброєні щитом і списом; лиця левові — обличчя їхні, і вони швидкі, як сарни в горах.","Головний Езер, другий Овадія, третій Елиав,","четвертий Мишманна, п’ятий Єремія,","шостий Афай, сьомий Елиел,","восьмий Іоханан, дев’ятий Елзавад,","десятий Єремія, одинадцятий Махбанай.","Вони із синів Гадових були главами у війську: менший над сотнею, і більший над тисячею.","Вони і перейшли Йордан у перший місяць, коли він виступає з берегів своїх, і розігнали всіх, хто жив у долинах на схід і захід.","Прийшли також і з синів Веніамінових та Іудиних в укріплення до Давида.","Давид вийшов назустріч їм і сказав їм: якщо з миром прийшли ви до мене, щоб допомагати мені, то нехай буде в мене з вами одне серце; а якщо для того, щоб підступно зрадити мене ворогам моїм, тоді як немає пороку на руках моїх, то нехай бачить Бог батьків наших і розсудить.","І охопив дух Амасая, главу тридцяти, і сказав він: мир тобі, Давиде, і з тобою, сину Ієссеїв; мир тобі, і мир помічникам твоїм; тому що допомагає тобі Бог твій. Тоді прийняв їх Давид і поставив їх на чолі війська.","І з коліна Манассіїного перейшли деякі до Давида, коли він ішов з филистимлянами на війну проти Саула, але не допомагав їм, тому що проводирі филистимські, порадившись, відіслали його, говорячи: на нашу голову він перейде до господаря свого Саула.","Коли він повертався в Секелаг, тоді перейшли до нього з манассіян: Аднах, Іозавад, Ієдиаел, Михаїл, Іозавад, Елигу і Цилльфай, тисячоначальники у манассіян.","І вони допомагали Давиду проти полчищ, бо все це були люди хоробрі і були начальниками у війську.","Так з кожним днем приходили до Давида на допомогу до того, що його ополчення стало великим, як ополчення Боже.","Ось число головних у війську, що прийшли до Давида у Хеврон, щоб передати йому царство Саулове, за словом Господнім:","синів Іудиних, які носять щит і спис, було шість тисяч вісімсот готових до війни;","із синів Симеонових, людей хоробрих, у війську було сім тисяч сто;","із синів Левіїних чотири тисячі шістсот;","й Іоддай, князь від племені Аарона, і з ним три тисячі сімсот;","і Садок, мужній юнак, і рід його, двадцять два начальники;","із синів Веніамінових, братів Саулових, три тисячі, — але ще багато хто з них тримався дому Саулового;","із синів Єфремових двадцять тисяч вісімсот людей мужніх, людей вельможних у родах своїх;","з половини коліна Манассіїного вісімнадцять тисяч, які викликані поіменно, щоб піти поставити царем Давида;","із синів Іссахарових прийшли люди розумні, які знали, що́ коли належало робити Ізраїлю, — їх було двісті головних, і всі брати їхні трималися слова їх;","з коліна Завулонового готових до битви, озброєних усякою військовою зброєю, п’ятдесят тисяч, у строю, одностайних;","з коліна Неффалимового тисяча вождів і з ними тридцять сім тисяч із щитами і списами;","з коліна Данового готових до війни двадцять вісім тисяч шістсот;","від Асира воїнів, готових до битви, сорок тисяч;","з-за Йордану, від коліна Рувимового, Гадового і половини коліна Манассіїного, сто двадцять тисяч, з усякою військовою зброєю.","Усі ці воїни, у строю, від щирого серця прийшли у Хеврон поставити Давида царем над усім Ізраїлем. Та й усі інші ізраїльтяни були одностайні, щоб поставити царем Давида.","І пробули там у Давида три дні, їли і пили, тому що брати їхні все приготували для них;","та й близькі до них, навіть до коліна Іссахарового, Завулонового і Неффалимового, привозили всю поживу на ослах, і верблюдах, і мулах, і волах: борошно, смокви, й ізюм, і вино, і єлей, і великої і дрібної худоби безліч, оскільки радість була для Ізраїля."],"x":{"1":"8.27.6","2":"6.20.16","8":"8.23.14|9.2.18","15":"5.3.15|30.24.28","18":"6.6.34","19":"8.29.4","21":"8.27.8","23":"8.16.12|9.5.1|12.11.3","28":"9.8.17","29":"9.3.6"}},{"v":["І радився Давид з тисячоначальниками, сотниками і з усіма вождями,","і сказав [Давид] усьому зібранню ізраїльтян: якщо угодно вам, і якщо на те буде воля Господа Бога нашого, пошлемо всюди до інших братів наших, по всій землі Ізраїльській, і разом з ними до священиків і левитів, у міста і селища їхні, щоб вони зібралися до нас;","і перенесемо до себе ковчег Бога нашого, тому що у дні Саула ми не зверталися до нього.","І сказало все зібрання: «нехай буде так», тому що ця справа всьому народові здавалася справедливою.","Так зібрав Давид усіх ізраїльтян, від Шихора єгипетського до входу в Емаф, щоб перенести ковчег Божий з Кириаф-Іарима.","І пішов Давид і весь Ізраїль у Кириаф-Іарим, що в Юдеї, щоб перенести звідти ковчег Бога, Господа, Який сидить на херувимах, на якому називається ім’я Його.","І повезли ковчег Божий на новій колісниці з дому Авинадава; й Оза й Ахия вели колісницю.","Давид же і всі ізраїльтяни грали перед Богом з усієї сили, зі співом, на цитрах і псалтирях, і тимпанах, і кимвалах і трубах.","Коли дійшли до току Хидона, Оза простяг руку свою, щоб притримати ковчег, тому що воли нахилили його.","Але Господь розгнівався на Озу, й уразив його за те, що він простяг руку свою до ковчега; і він помер одразу перед лицем Божим.","І засмутився Давид, що Господь уразив Озу. І назвав те місце поразкою Ози; так називається воно і до цього дня.","І злякався Давид Бога в день той, і сказав: як я внесу до себе ковчег Божий?","І не повіз Давид ковчег до себе, у місто Давидове, а повернув його до дому Аведдара гефянина.","І залишався ковчег Божий у Аведдара, у домі його, три місяці, і благословив Господь дім Аведдара й усе, що в нього."],"x":{"1":"9.6.2","5":"9.6.1","6":"8.4.4|9.6.2|11.19.15","7":"3.4.15|9.6.3","9":"9.6.6","10":"3.4.15","11":"9.6.8","14":"9.6.11"}},{"v":["І послав Хирам, цар Тирський, до Давида послів, і кедрові дерева, і мулярів, і теслярів, щоб побудувати йому дім.","Коли довідався Давид, що утвердив його Господь царем над Ізраїлем, що піднесено високо царство його, заради народу його Ізраїля,","тоді взяв Давид ще дружин в Єрусалимі, і породив Давид ще синів і дочок.","І ось імена народжених у нього в Єрусалимі: Самус, Совав, Нафан, Соломон,","Евеар, Елисуа, Елфалет,","Ногах, Нафек, Іафіа,","й Елисама, Вееліада й Елифалеф.","І почули филистимляни, що помазано Давида на царя над усім Ізраїлем, і піднялися усі филистимляни шукати Давида. І почув Давид про це і пішов проти них.","І филистимляни прийшли і розташувалися в долині рефаїмів.","І запитав Давид Бога, говорячи: чи йти мені проти филистимлян, і чи віддаси їх у руки мої? І сказав йому Господь: іди, і Я віддам їх у руки твої.","І пішли вони у Ваал-Перацим, і вразив їх там Давид; і сказав Давид: зломив Бог ворогів моїх рукою моєю, як прорив води. Тому і дали ім’я місцю тому: Ваал-Перацим.","І залишили там филистимляни богів своїх, і повелів Давид, і спалені вони вогнем.","І прийшли знову филистимляни і розташувалися по долині.","І ще запитав Давид Бога, і сказав йому Бог: не ходи прямо на них, ухилися від них і йди до них з боку шовковичних дерев;","і коли почуєш шум, ніби кроків на вершинах шовковичних дерев, тоді вступи в битву, бо вийшов Бог перед тобою, щоб уразити стан филистимлян.","І зробив Давид, як повелів йому Бог; і вразили стан филистимський, від Гаваона до Газера.","І пронеслося ім’я Давидове по всіх землях, і Господь зробив його страшним для всіх народів."],"x":{"1":"9.5.11","3":"9.5.13","4":"9.5.14|12.3.5","8":"9.5.17:20","11":"9.5.20","12":"4.7.5","13":"9.5.22","16":"9.5.25"}},{"v":["І побудував він собі доми в місті Давидовому, і приготував місце для ковчега Божого, і спорудив для нього скинію.","Тоді сказав Давид: ніхто не повинен носити ковчега Божого, крім левитів, тому що їх обрав Господь на те, щоб носити ковчег Божий і служити Йому повіки.","І зібрав Давид усіх ізраїльтян в Єрусалим, щоб внести ковчег Господній на місце його, яке він для нього приготував.","І скликав Давид синів Ааронових і левитів:","із синів Каафових, Уриїла начальника і братів його — сто двадцять чоловік;","із синів Мерариних, Асаію начальника і братів його — двісті двадцять чоловік;","із синів Гирсонових Іоїля начальника і братів його — сто тридцять чоловік;","із синів Елисафанових, Шемаію начальника і братів його — двісті;","із синів Хевронових, Елиєла начальника і братів його — вісімдесят;","із синів Уззиїлових, Аминадава начальника і братів його — сто дванадцять.","І прикликав Давид священиків: Садока й Авиафара, і левитів: Уриїла, Асаію, Іоїля, Шемаію, Елиєла й Аминадава,","і сказав їм: ви, начальники родів левитських, освятіться самі і брати ваші, і принесіть ковчег Господа Бога Ізраїлевого на місце, яке я приготував для нього;","бо як раніше не ви це робили, то Господь Бог наш уразив нас за те, що ми не шукали Його, як належало.","І освятилися священики і левити для того, щоб нести ковчег Господа, Бога Ізраїлевого.","І понесли сини левитів ковчег Божий, як заповів Мойсей за словом Господа, на плечах, на жердинах.","І наказав Давид начальникам левитів поставити братів своїх співців з музичними інструментами, з псалтирями і цитрами і кимвалами, щоб вони голосно сповіщали голос радування.","І поставили левити Емана, сина Іоїлевого, і з братів його, Асафа, сина Верехиїного, а із синів Мерариних, братів їхніх, Ефана, сина Кушаії;","і з ними братів їхніх другорядних: Захарію, Бена, Іаазиїла, Шемирамофа, Ієхиїла, Уннія, Елиава, Ванею, Маасея, Маттафію, Елифлеуя, Микнея й Овед-Едома та Ієїела, воротарів.","Еман, Асаф і Ефан грали голосно на мідних кимвалах,","а Захарія, Азиїл, Шемирамоф, Ієхиїл, Унній, Елиав, Маасей і Ванея — на псалтирях, тонким голосом.","Маттафія ж, Елифлеуй, Микней, Овед-Едом, Ієїел і Азазія — на цитрах, щоб робити початок.","А Хенанія, начальник левитів, був учитель співу, тому що був вправним у ньому.","Верехія й Елкана були придверниками біля ковчега.","Шеванія, Іосафат, Нафанаїл, Амасай, Захарія, Ванея та Елиєзер, священики, сурмили трубами перед ковчегом Божим. Овед-Едом та Ієхія були придверниками біля ковчега.","Так Давид і старійшини Ізраїлеві і тисячоначальники пішли перенести ковчег завіту Господнього з дому Овед-Едомового з радістю.","І коли Бог допоміг левитам, які несли ковчег завіту Господнього, тоді закололи в жертву сім тельців і сім баранів.","Давид був одягнений у висонний одяг, а також і всі левити, які несли ковчег, і співці, і Хенанія начальник музикантів і співаків. На Давиді ж був ще лляний ефод.","Так весь Ізраїль вносив ковчег завіту Господнього з вигуками, під звуки рога і труб і кимвалів, граючи на псалтирях і цитрах.","Коли ковчег завіту Господнього входив у місто Давидове, Мелхола, дочка Саулова, дивилася у вікно і, побачивши царя Давида, який скакає і веселиться, принизила його в серці своєму."],"x":{"1":"9.6.17","2":"3.4.15","3":"12.13.5","12":"3.8.6","13":"12.13.11|9.6.7","15":"1.25.14","16":"9.6.12","17":"12.16.37","18":"12.16.38","25":"9.6.12"}},{"v":["І принесли ковчег Божий, і поставили його посеред скинії, яку спорудив для нього Давид, і піднесли Богу всепалення і мирні жертви.","Коли Давид закінчив всепалення і приношення мирних жертв, то благословив народ ім’ям Господа","і роздав усім ізраїльтянам, і чоловікам і жінкам, по одній хлібині і по шматку м’яса і по кухлю вина,","і поставив на службу перед ковчегом Господнім деяких з левитів, щоб вони славословили, дякували і звеличували Господа Бога Ізраїлевого:","Асафа головним, другим по ньому Захарію, Ієїела, Шемирамофа, Ієхиїла, Маттафію, Елиава, і Ванею, Овед-Едома та Ієїела з псалтирями і цитрами, і Асафа для гри на кимвалах,","а Ванею та Озиїла, священиків, щоб постійно сурмили перед ковчегом завіту Божого.","У цей день Давид уперше дав псалом для славослів’я Господу через Асафа, і братів його:","славте Господа, проголошуйте ім’я Його; сповіщайте в народах діла Його;","співайте Йому, бряжчіть Йому; оповідайте про всі чудеса Його;","хваліться ім’ям Його святим; нехай веселиться серце тих, хто шукає Господа;","шукайте Господа і сили Його, шукайте безперестанно лиця Його;","поминайте чудеса, які Він сотворив, знамення Його і суди вуст Його,","ви, сíм’я Ізраїлеве, раби Його, сини Якова, обрані Його!","Він Господь Бог наш; суди Його по всій землі.","Пам’ятайте вічно завіт Його, слово, яке Він заповів у тисячу родів,","те, що заповідав Аврааму, і в чому клявся Ісааку,","і що поставив Якову в закон і Ізраїлю в завіт вічний,","говорячи: «тобі дам Я землю Ханаанську, у спадкоємний наділ вам».","Вони були тоді нечисленні і незначні, і прибульці в ній,","і переходили від народу до народу і з одного царства до іншого народу;","але Він нікому не дозволив кривдити їх, і викривав за них царів:","«Не доторкайтеся до помазаних Моїх, і пророкам Моїм не робіть зла».","Співайте Господу, вся земле, благовістіть з дня у день спасіння Його.","Сповіщайте язичникам славу Його, усім народам чудеса Його,","бо великий Господь і славний, страшніший за всіх богів.","Тому що всі боги народів ніщо, а Господь небеса сотворив.","Слава і велич перед лицем Його, могутність і радість на місці [святому] Його.","Воздайте Господу, племена народів, воздайте Господу славу і честь,","воздайте Господу славу імені Його. Візьміть дар, ідіть перед лице Його, поклоніться Господу у величі святині Його.","Тремти перед Ним, уся земле, бо Він заснував вселенну, вона не похитнеться.","Нехай веселяться небеса, нехай торжествує земля, і нехай скажуть у народах: Господь царює!","Нехай плеще море і все, що наповнює його, нехай радіє поле й усе, що на ньому.","Нехай радіють разом усі дерева дібровні перед лицем Господа, бо Він іде судити землю.","Прославляйте Господа, бо повіки милість Його,","і скажіть: спаси нас, Боже, Спасителю наш! Збери нас і визволи нас від народів, щоб ми славили святе ім’я Твоє і щоб хвалилися славою Твоєю!","Благословенний Господь Бог Ізраїлів, від віку і до віку! І сказав увесь народ: амінь! алилуя!","Давид залишив там, перед ковчегом завіту Господнього, Асафа і братів його, щоб вони служили перед ковчегом постійно, щодня,","й Овед-Едома і братів його, шістдесят вісім чоловік; Овед-Едома, сина Ідифунового, і Хосу — воротарями,","а Садока священика і братів його священиків перед оселею Господньою, яка на висоті в Гаваоні,","для возношення всепалень Господу на жертовнику всепалення постійно, вранці і ввечері, і для усього, що написано в законі Господа, який Він заповів Ізраїлю;","і з ними Емана та Ідифуна й інших обраних, які призначені поіменно, щоб славити Господа, бо навіки милість Його.","При них Еман та Ідифун прославляли Бога, граючи на трубах, кимвалах і різних музичних інструментах; синів же Ідифуна поставив при вратах.","І пішов увесь народ, кожен у свій дім; повернувся і Давид, щоб благословити дім свій."],"x":{"1":"9.6.17","2":"9.6.18","3":"9.6.19","8":"31.12.4","15":"0.17.9|1.2.24|2.26.42","16":"0.12.7|0.22.16|52.1.73","19":"4.32.9","22":"25.104.15","23":"25.95.1","24":"25.95.3","25":"25.94.3|1.15.11|1.18.11","27":"25.95.6","34":"14.3.11","35":"4.30.3","36":"25.40.14|4.27.15|17.8.6","40":"1.27.21|3.28.3","43":"9.6.19"}},{"v":["Коли Давид жив у домі своєму, то сказав Давид Нафану пророку: ось, я живу в домі кедровому, а ковчег завіту Господнього під наметом.","І сказав Нафан Давиду: все, що в тебе на серці, роби, тому що з тобою Бог.","Але в ту ж ніч було слово Боже до Нафана:","піди і скажи рабові Моєму Давиду: так говорить Господь: не ти побудуєш Мені дім для перебування,","бо Я не жив у домі з того дня, як вивів синів Ізраїля, і до цього дня, а ходив зі скинії у скинію і з житла в житло.","Де не ходив Я з усім Ізраїлем, чи сказав Я хоч слово кому-небудь із суддів ізраїльських, яким Я повелів пасти народ Мій: чому ви не побудуєте Мені дому кедрового?","І тепер так скажи рабові Моєму Давиду: так говорить Господь Саваоф: Я взяв тебе від отари овець, щоб ти був вождем народу Мого Ізраїля;","і був з тобою скрізь, куди б ти не ходив, і знищив усіх ворогів твоїх перед лицем твоїм, і зробив ім’я твоє, як ім’я великих на землі;","і Я влаштував місце для народу Мого Ізраїля, й укорінив його, і буде він спокійно жити на місці своєму, і не буде більше потривожений, і нечестиві не стануть більше тіснити його, як раніше,","у ті дні, коли Я поставив суддів над народом Моїм Ізраїлем, і Я смирив усіх ворогів твоїх, і сповіщаю тобі, що Господь спорудить тобі дім.","Коли виповняться дні твої, і ти відійдеш до батьків твоїх, тоді Я восставлю сíм’я твоє після тебе, яке буде із синів твоїх, і зміцню царство його.","Він побудує Мені дім, і утверджу престіл його повіки.","Я буду йому отцем, і він буде Мені сином, — і милости Моєї не відніму від нього, як Я відняв від того, який був раніше тебе.","Я поставлю його в домі Моєму й у царстві Моєму повіки, і престіл його буде міцним вічно.","Всі ці слова і все видіння точно переказав Нафан Давиду.","І прийшов цар Давид, і став перед лицем Господнім, і сказав: хто я, Господи Боже, і що таке дім мій, що Ти так підніс мене?","Але і цього ще мало здалося в очах Твоїх, Боже; Ти звіщаєш про дім раба Твого у майбутньому, і дивишся на мене, як на людину велику, Господи Боже!","Що ще може додати перед Тобою Давид для звеличення раба Твого? Ти знаєш раба Твого!","Господи! для раба Твого, за серцем Твоїм, Ти робиш усе це велике, щоб явити усяку велич.","Господи! Немає подібного до Тебе, і немає Бога, крім Тебе, в усьому, що чули ми своїми вухами.","І хто подібний до народу Твого Ізраїля, єдиного народу на землі, до якого приходив Бог, щоб викупити його Собі в народ, зробити Собі ім’я великим і страшним ділом — прогнанням народів від лиця народу Твого, який Ти визволив з Єгипту.","Ти зробив народ Твій Ізраїля Своїм власним народом навік, і Ти, Господи, став Богом його.","Отже, тепер, о, Господи, слово, яке Ти сказав про раба Твого і про дім його, утверди навік, і зроби, як Ти сказав.","І нехай перебуває і звеличується ім’я Твоє повіки, щоб говорили: Господь Саваоф, Бог Ізраїлів, є Бог над Ізраїлем, і дім раба Твого Давида нехай буде міцним перед лицем Твоїм.","Бо Ти, Боже мій, відкрив рабові Твоєму, що Ти спорудиш йому дім, тому раб Твій і насмілився молитися перед Тобою.","І нині, Господи, Ти Бог, і Ти сказав про раба Твого таке благо.","Почни ж благословляти дім раба Твого, щоб він був вічно перед лицем Твоїм. Бо якщо Ти, Господи, благословиш, то буде він благословенний повік."],"x":{"1":"9.7.2","2":"9.7.3","3":"9.7.4-5","4":"10.8.19","5":"1.7.5","7":"8.16.12","9":"9.7.10","10":"25.17.48","11":"9.7.12|65.3.16|50.1.1","13":"9.7.14","14":"71.3.15|31.55.3|52.1.32","15":"9.7.17","16":"9.7.18","17":"9.7.19","18":"25.138.1","20":"9.7.22","21":"4.4.7","23":"9.7.25","25":"9.7.27","27":"9.7.29"}},{"v":["Після цього Давид уразив филистимлян і смирив їх, і взяв Геф і залежні від нього міста з рук филистимлян.","Він уразив також моавитян, — і стали моавитяни рабами Давида, приносячи йому данину.","І вразив Давид Адраазара, царя Сувського, в Емафі, коли той ішов утвердити владу свою при ріці Євфраті.","І взяв Давид у нього тисячу колісниць, сім тисяч вершників і двадцять тисяч піших, і зруйнував Давид усі колісниці, залишивши з них тільки сто.","Сиріяни дамаські прийшли було на допомогу Адраазару, царю Сувському, але Давид уразив двадцять дві тисячі сиріян.","І поставив Давид охоронне військо в Сирії дамаській, і стали сиріяни рабами Давида, приносячи йому данину. І допомагав Господь Давиду скрізь, куди б він не ходив.","І взяв Давид золоті щити, що були в рабів Адраазара, і приніс їх в Єрусалим.","А з Тивхави і Куна, міст Адраазарових, узяв Давид дуже багато міді. З неї Соломон зробив мідне море і стовпи, і мідні посудини.","І почув Фой, цар Імафа, що Давид уразив усе військо Адраазара, царя Сувського.","І послав Іорама, сина свого, до царя Давида, вітати його і дякувати йому за те, що він воював з Адраазаром і вразив його, тому що Фой був у стані війни з Адраазаром, — і з ним усякі посудини золоті, срібні та мідні.","І присвятив їх цар Давид Господу разом зі сріблом і золотом, яке він узяв від усіх народів: від ідумеян, моавитян, аммонитян, филистимлян і від амаликитян.","І Авесса, син Саруї, вразив ідумеян на долині Соляній вісімнадцять тисяч;","і поставив у Ідумеї охоронне військо, і стали всі ідумеяни рабами Давида. Господь допомагав Давиду скрізь, куди б він не ходив.","І царював Давид над усім Ізраїлем, і творив суд і правду всьому народові своєму.","Іоав, син Саруї, був начальником війська, Іосафат, син Ахилуда, діловодом,","Садок, син Ахитува, й Авимелех, син Авиафара, священиками, а Суса писарем,","Ванея, син Іодая, над хелефеями і фелефеями, а сини Давидові — першими при царі."],"x":{"1":"9.8.1","2":"9.8.2|25.29.2","6":"9.8.14","7":"9.8.7","8":"9.8.8|10.7.23","9":"9.8.9","12":"12.2.16|9.8.13|25.59.2","14":"9.8.15|25.100.1","15":"9.8.16","16":"12.24.6","17":"9.8.18"}},{"v":["Після цього помер Наас, цар Аммонитський, і став царем син його замість нього.","І сказав Давид: зроблю я милість Аннону, синові Наасовому, за благодіяння, які батько його зробив мені. І послав Давид послів утішити його щодо батька його; і прийшли слуги Давидові в землю Аммонитську, до Аннона, щоб утішити його.","Але князі аммонитські сказали Аннону: невже ти думаєш, що Давид з поваги до батька твого послав до тебе утішителів? Чи не для того прийшли слуги його до тебе, щоб розвідати і виглядіти землю і розорити її?","І взяв Аннон слуг Давидових і поголив їх, і обрізав одяг їхній наполовину до стегон і відпустив їх.","І пішли вони. І донесено було Давиду про людей цих, і він послав їм назустріч, бо вони були дуже знечещені; і сказав цар: залиштеся в Єрихоні, поки відростуть бороди ваші, і тоді повернетеся.","Коли аммонитяни побачили, що вони стали ненависними Давиду, тоді послав Аннон і аммонитяни тисячу талантів срібла, щоб найняти собі колісниці і вершників із Сирії месопотамської і з Сирії Мааха і з Суви.","І найняли собі тридцять дві тисячі колісниць і царя Мааха з народом його, які прийшли і розташувалися станом перед Медевою. І аммонитяни зібралися з міст своїх і виступили на війну.","Коли почув про це Давид, то послав Іоава з усім військом хоробрих.","І виступили аммонитяни і вишикувалися до битви біля воріт міста, а царі, які прийшли, окремо в полі.","Іоав, бачачи, що чекає на нього битва попереду і ззаду, обрав воїнів з усіх добірних в Ізраїлі і вишикував їх проти сиріян.","А іншу частину народу доручив Авессі, братові своєму, щоб вони вишикувалися проти аммонитян.","І сказав він: якщо сиріяни будуть долати мене, то ти допоможеш мені, а якщо аммонитяни будуть долати тебе, то я допоможу тобі.","Будь мужній, і будемо твердо стояти за народ наш і за міста Бога нашого, — і Господь нехай зробить, що Йому вгодно.","І вступили Іоав і люди, які були в нього, на битву з сиріянами, і вони побігли від нього.","Аммонитяни ж, побачивши, що сиріяни біжать, і самі побігли від Авесси, брата його, і пішли в місто. І прийшов Іоав у Єрусалим.","Сиріяни, бачачи, що вони вражені ізраїльтянами, відправили послів і вивели сиріян, які були по той бік ріки, і Совак, воєначальник Адраазарів, був проводирем їхнім.","Коли донесли про це Давиду, він зібрав усіх ізраїльтян, перейшов Йордан і, прийшовши до них, вишикувався проти них; і вступив Давид у битву з сиріянами, і вони воювали з ним.","І сиріяни побігли від ізраїльтян, і знищив Давид у сиріян сім тисяч колісниць і сорок тисяч піших, і Совака воєначальника умертвив.","Коли побачили слуги Адраазара, що вони вражені ізраїльтянами, уклали з Давидом мир і підкорилися йому. І більше не хотіли сиріяни допомагати аммонитянам."],"x":{"1":"9.10.1","3":"9.10.3","4":"9.10.4","11":"9.10.10","13":"8.3.18|9.10.12|21.3.60","16":"9.10.15","19":"9.10.19"}},{"v":["Через рік, у той час, коли царі виходять на війну, вивів Іоав військо і став розоряти землю аммонитян, і прийшов і обложив Равву. Давид же залишався в Єрусалимі. Іоав, завоювавши Равву, зруйнував її.","І взяв Давид вінець царя їхнього з голови його, і в ньому виявилося ваги талант золота, і дорогоцінні камені були на ньому; і був він покладений на голову Давида. І дуже багато здобичі виніс з міста.","А народ, який був у ньому, вивів і умертвляв їх пилами, залізними молотами і сокирами. Так зробив Давид з усіма містами аммонитян, і повернувся Давид і весь народ в Єрусалим.","Після того почалася війна з филистимлянами в Газері. Тоді Совохай хушатянин уразив Сафа, одного з нащадків рефаїмів. І вони смирилися.","І знову була війна з филистимлянами. Тоді Елханам, син Іаїра, вразив Лахмия, брата Голіафового, гефянина, у якого древко списа було, як навій у ткачів.","Була ще битва у Гефі. Там був один великий на зріст чоловік, у якого було по шість пальців, всього двадцять чотири. І він також був з нащадків рефаїмів.","Він ганьбив Ізраїля, але Іонафан, син Шими, брата Давидового, вразив його.","Це були народжені від рефаїмів у Гефі, і впали від руки Давида і від руки слуг його."],"x":{"1":"9.11.1","2":"9.12.30","4":"9.21.18","5":"9.21.19","6":"9.21.20","7":"8.16.9"}},{"v":["І повстав сатана на Ізраїля, і підбурив Давида зробити перелік ізраїльтян.","І сказав Давид Іоаву і начальникам у народі: підіть порахуйте ізраїльтян, від Вирсавії до Дана, і представте мені, щоб я знав число їх.","І сказав Іоав: нехай примножить Господь народ Свій у сто разів проти того, скільки є його. Чи не всі вони, господарю мій царю, раби господаря мого? Для чого ж вимагає цього господар мій? Щоб було поставлено це в провину Ізраїлю?","Але царське слово перемогло Іоава; і пішов Іоав, і обійшов увесь Ізраїль, і прийшов у Єрусалим.","І подав Іоав Давиду список народного перепису, і було всіх ізраїльтян тисяча тисяч, і сто тисяч чоловіків, які оголюють меч, і юдеїв — чотириста сімдесят тисяч, які оголюють меч.","А левитів і веніаминян він не порахував між ними, тому що царське слово було противним Іоаву.","І не угодною була в очах Божих справа ця, і Він уразив Ізраїля.","І сказав Давид Богу: дуже згрішив я, зробивши це. І нині прости провину раба Твого, бо я зробив дуже нерозважливо.","І говорив Господь Гадові, прозорливцю Давидовому, і сказав:","піди і скажи Давиду: так говорить Господь: три покарання Я пропоную тобі, обери собі одне з них, — і Я пошлю його на тебе.","І прийшов Гад до Давида і сказав йому: так говорить Господь: обирай собі:","або три роки — голод, або три місяці будеш ти переслідуваний ворогами твоїми і меч ворогів твоїх буде досягати тебе; або три дні — меч Господній і моровиця на землі й ангел Господній, який знищує в усіх краях Ізраїля. Отже, розглянь, що мені відповісти Тому, Хто Послав мене зі словом.","І сказав Давид Гадові: тяжко мені дуже, але нехай краще впаду в руки Господа, бо дуже велике милосердя Його, тільки б не впасти мені в руки людські.","І послав Господь моровицю на Ізраїля, і померло ізраїльтян сімдесят тисяч чоловік.","І послав Бог ангела в Єрусалим, щоб знищувати його. І коли він почав знищувати, побачив Господь і пожалів про цю біду, і сказав ангелу-знищувачу: досить! тепер опусти руку твою. Ангел же Господній стояв тоді над током Орни ієвусеянина.","І підняв Давид очі свої, і побачив ангела Господнього, який стоїть між землею і небом, з оголеним у руці його мечем, простягнутим на Єрусалим; і впав Давид і старійшини, покриті веретищем, на обличчя свої.","І сказав Давид Богу: чи не я повелів порахувати народ? я згрішив, я зробив зло, а ці вівці що зробили? Господи, Боже мій! нехай буде рука Твоя на мені і на домі батька мого, а не на народі Твоєму, щоб погубити його.","І ангел Господній сказав Гадові, щоб той сказав Давиду: нехай Давид прийде і поставить жертовник Господу на току Орни ієвусеянина.","І пішов Давид, за словом Гада, яке він говорив ім’ям Господнім.","Орна повернувся, побачив ангела, і чотири сини його з ним сховалися. Орна молотив тоді пшеницю.","І прийшов Давид до Орни. Орна, глянувши і побачивши Давида, вийшов з току і поклонився Давиду лицем до землі.","І сказав Давид Орні: віддай мені місце під током, я побудую на ньому жертовник Господу; за справжню ціну віддай мені його, щоб припинилося знищення народу.","І сказав Орна Давиду: візьми собі; нехай робить господар мій цар що йому вгодно; ось я віддаю і волів на всепалення, і молотильні знаряддя на дрова, і пшеницю на приношення; усе це віддаю задарма.","І сказав цар Давид Орні: ні, я хочу купити в тебе за дійсну ціну, бо не стану я приносити твоєї власности Господу, і не буду приносити у всепалення взятого задарма.","І дав Давид Орні за це місце шістсот сиклів золота.","І спорудив там Давид жертовник Господу і підніс всепалення і мирні жертви; і призвав Господа, і Він почув його, пославши вогонь з неба на жертовник всепалення.","І сказав Господь ангелові: поверни меч твій у піхви його.","У цей час Давид, бачачи, що Господь почув його на току Орни ієвусеянина, приніс там жертву.","Скинія ж Господня, яку зробив Мойсей у пустелі, і жертовник всепалення знаходилися в той час на висоті в Гаваоні.","Й не міг Давид піти туди, щоб шукати Бога, тому що був наляканий мечем ангела Господнього."],"x":{"1":"9.24.1","4":"9.24.4","7":"12.27.24","8":"9.24.10","9":"9.24.11|8.9.9","11":"9.24.13","13":"9.24.14|33.3.22|30.2.18","15":"9.24.16","17":"9.24.17","18":"9.24.18|13.3.1","21":"9.14.4","26":"9.24.25|2.9.24|10.18.38","29":"9.6.17|13.1.3"}},{"v":["І сказав Давид: ось дім Господа Бога й ось жертовник для всепалення Ізраїля.","І наказав Давид зібрати прибульців, які знаходилися в землі Ізраїльській, і поставив каменотесів, щоб обтесувати камені для побудови дому Божого.","І багато заліза для цвяхів до дверей воріт і для зв’язок заготував Давид, і багато міді без ваги,","і кедрових дерев без ліку, тому що сидоняни і тиряни доставили Давиду багато кедрових дерев.","І сказав Давид: Соломон, син мій, молодий і слабосилий, а дім, який слід побудувати для Господа, повинен бути дуже величним, на славу і прикрасу перед усіма землями: отже, я буду заготовляти для нього. І заготував Давид до смерти своєї багато.","І прикликав Соломона, сина свого, і заповів йому побудувати дім Господу Богу Ізраїлевому.","І сказав Давид Соломону: сину мій! у мене було на серці побудувати дім в ім’я Господа, Бога мого,","але було до мене слово Господнє, і сказано: «ти пролив багато крови і вів великі війни; ти не повинен будувати дому імені Моєму, тому що пролив багато крови на землю перед лицем Моїм.","Ось, у тебе народиться син: він буде чоловіком мирним; Я дам йому спокій від усіх ворогів його навкруги: тому ім’я йому буде Соломон. І мир і спокій дам Ізраїлю у дні його.","Він побудує дім імені Моєму, і він буде Мені сином, а Я йому отцем, і утверджу престіл царства його над Ізраїлем повік».","І нині, сину мій! нехай буде Господь з тобою, щоб ти мав благий успіх і побудував дім Господу Богу твоєму, як Він говорив про тебе.","Нехай дасть тобі Господь сенс і розум, і поставить тебе над Ізраїлем; і дотримуйся закону Господа Бога твого.","Тоді ти будеш мати благий успіх, якщо будеш намагатися виконувати устави і закони, які заповів Господь Мойсеєві для Ізраїля. Будь твердим і мужнім, не бійся і не сумуй.","І ось, я за убогости моєї приготував для дому Господнього сто тисяч талантів золота і тисячу тисяч талантів срібла, а міді і залізу немає ваги, тому що їх безліч; і дерева і камені я також заготував, а ти ще додай до цього.","У тебе багато робітників і каменотесів, різьбярів і теслярів, і всяких здібних до всякої справи;","золоту, сріблу і міді та залізу немає ліку: почни і роби; Господь буде з тобою.","І заповів Давид усім князям Ізраїлевим допомагати Соломону, синові його:","чи не з вами Господь Бог наш, Який дав вам спокій з усіх боків? тому що Він віддав у руки мої жителів землі, і підкорилася земля перед Господом і перед народом Його.","Отже, налаштуйте серце ваше і душу вашу на те, щоб шукати Господа Бога вашого. Встаньте і побудуйте святилище Господу Богу, щоб перенести ковчег завіту Господнього і священні сосуди у Божий дім, що споруджується імені Господньому."],"x":{"1":"4.12.5|12.21.26","2":"13.2.17|10.5.15","5":"12.29.1","7":"12.17.1","8":"12.28.3","9":"9.7.11","10":"9.7.13|10.5.5|75.1.5","13":"4.31.6|5.1.7|10.2.2","14":"12.29.2"}},{"v":["Давид, постарівши і наситившись життям, поставив царем над Ізраїлем сина свого Соломона.","І зібрав усіх князів ізраїльських і священиків і левитів,","і перелічені були левити, від тридцяти років і вище, і було число їх, рахуючи поголовно, тридцять вісім тисяч чоловік.","З них призначені для справи в домі Господньому двадцять чотири тисячі, писарів же і суддів шість тисяч,","і чотири тисячі воротарів, і чотири тисячі, які прославляють Господа на музичних інструментах, які він зробив для прославляння.","І розділив їх Давид на черги за синами Левія — Гирсоном, Каафою і Мерарі.","Із гирсонян — Лаедан і Шимей.","Сини Лаедана: перший Ієхиїл, Зефам та Іоїль, троє.","Сини Шимея: Шеломиф, Хазиїл і Гаран, троє. Вони глави поколінь Лаеданових.","Ще сини Шимея: Іахаф, Зиза, Ієуш і Берія. Це сини Шимея, четверо.","Іахаф був головним, Зиза другим; Ієуш і Берія мали дітей мало, і тому вони були в одному рахунку з домом батька.","Сини Каафа: Амрам, Іцгар, Хеврон і Озиїл, четверо.","Сини Амрама: Аарон і Мойсей. Аарон відділений був на присвяту до Святого Святих, він і сини його, навіки, щоб звершувати куріння перед лицем Господа, щоб служити Йому і благословляти ім’ям Його повіки.","А Мойсей, чоловік Божий, і сини його приєднані до коліна Левіїного.","Сини Мойсея: Гирсон і Єлиєзер.","Сини Гирсона: перший був Шевуїл.","Сини Єлиєзера були: перший Рехавія. І не було в Єлиєзера інших синів; у Рехавії ж було дуже багато синів.","Сини Іцгара: перший Шеломиф.","Сини Хеврона: перший Ієрія і другий Амарія, третій Іахазиїл і четвертий Ієкамам.","Сини Озиїла: перший Миха і другий Ішшия.","Сини Мерарині: Махлі і Муші. Сини Махлі: Єлеазар і Кис.","І помер Єлеазар, і не було в нього синів, а тільки дочки; і взяли їх за себе сини Киса, брати їхні.","Сини Муші: Махлі, Едер та Іремоф — троє.","Ось сини Левіїні, за домами батьків їхніх, глави родин, за поіменним численням їх поголовно, які відправляли діла служіння в домі Господньому, від двадцяти років і вище.","Бо Давид сказав: Господь, Бог Ізраїлів, дав спокій народу Своєму й оселив його в Єрусалимі навіки,","і левитам не треба носити скинію і всякі речі її для служіння в ній.","Тому, за останніми повеліннями Давида, пораховані левити від двадцяти років і вище,","щоб вони були при синах Ааронових, для служіння дому Господньому, у дворі й у прибудовах, для дотримання чистоти усього святилища і для виконання всякої служби при домі Божому,","для спостереження за хлібами предкладення і пшеничним борошном для хлібного приношення, і прісними коржами, за печеним, смаженим і за всякою мірою і вагою,","і щоб ставали щоранку складати подяку і славословити Господа, також і ввечері,","і при усіх всепаленнях, що возносяться Господу в суботи, у новомісяччя й у свята за числом, як написано про них, — постійно перед лицем Господа,","і щоб охороняли скинію одкровення і святилище і синів Ааронових, братів своїх, при службах дому Господньому."],"x":{"1":"10.1.33","3":"3.4.3|3.8.24","4":"4.16.18","5":"12.9.22|36.40.44|13.29.25","6":"13.8.14|12.6.1|1.6.16|3.3.17|3.26.57","12":"1.6.18","13":"1.6.20|3.3.10|75.5.4","15":"1.2.22|1.18.3","19":"12.24.23-24","21":"1.6.19|12.6.19","22":"12.24.28","24":"3.8.24","28":"13.31.17"}},{"v":["І ось розподіл синів Ааронових: сини Аарона: Надав, Авиуд, Єлеазар та Іфамар.","Надав і Авиуд померли раніше батька свого, синів же не було в них, і тому священствували Єлеазар та Іфамар.","І розподілив їх Давид — Садока із синів Єлеазара, й Ахимелеха із синів Іфамара, за чергою на службу їх.","І сталося, що між синами Єлеазара глав поколінь більше, ніж між синами Іфамара. І він розподілив їх так: із синів Єлеазара шістнадцять глав родин, а із синів Іфамара вісім.","Розподіляв же їх за жеребами, тому що головними у святилищі і головними перед Богом були з синів Єлеазара і з синів Іфамара,","і записував їх Шемаія, син Нафанаїла, писар з левитів, перед лицем царя і князів і перед священиком Садоком і Ахимелехом, сином Авиафара, і перед главами родин священичих і левитських: брали при киданні жереба одну родину з роду Єлеазарового, потім брали з роду Іфамарового.","І випав перший жереб Ієгоїариву, другий Ієдаії,","третій Хариму, четвертий Сеориму,","п’ятий Малхію, шостий Миямину,","сьомий Гаккоцу, восьмий Авиї,","дев’ятий Ієшую, десятий Шеханії,","одинадцятий Елиашиву, дванадцятий Іакиму,","тринадцятий Хушаю, чотирнадцятий Ієшеваву,","п’ятнадцятий Вилзі, шістнадцятий Імеру,","сімнадцятий Хезиру, вісімнадцятий Гапицецу,","дев’ятнадцятий Петахії, двадцятий Єзекиїлю,","двадцять перший Іахину, двадцять другий Гамулу,","двадцять третій Делаії, двадцять четвертий Маазії.","Ось порядок їх при служінні їх, як їм приходити в дім Господній, за уставом їхнім через Аарона, батька їхнього, як заповів йому Господь Бог Ізраїлів.","У інших синів Левія — розподіл: із синів Амрама: Шуваїл; із синів Шуваїла: Ієдія;","від Рехавії: із синів Рехавії Ішшія був перший;","від Іцгара: Шеломоф; із синів Шеломофа: Іахав;","із синів Хеврона: перший Ієрія, другий Амарія, третій Іахазиїл, четвертий Ієкамам.","Із синів Озиїла: Миха; із синів Михи: Шамир.","Брат Михи Ішшія; із синів Ішшії: Захарія.","Сини Мерарі: Махлі і Муші; з синів Іаазії: Бено.","Із синів Мерарі в Іаазії: Бено і Шогам, і Заккур та Іврі.","У Махлія — Єлеазар; у нього синів не було.","У Киса: із синів Киса: Ієрахмиїл;","сини Муші: Махлі, Едер та Ієримоф. Ось сини левитів за поколіннями їх.","Кидали і вони жереб, нарівні з братами своїми, синами Аароновими, перед лицем царя Давида і Садока й Ахимелеха, і глав родин священичих і левитських: глава родини нарівні з меншим братом своїм."],"x":{"1":"3.3.2","2":"3.3.4|3.26.61","5":"52.1.5","6":"12.18.16","9":"32.21.1","19":"13.31.2|11.11.5","23":"12.23.19","28":"12.23.22","30":"12.23.23","31":"12.25.8"}},{"v":["І відокремив Давид і начальники війська на службу синів Асафа, Емана та Ідифуна, щоб вони провіщали на цитрах, псалтирях і кимвалах; і були відраховані вони на справу служіння свого:","із синів Асафа: Заккур, Йосиф, Ієфанія й Ашарела сини Асафа, під керівництвом Асафа, який грав за настановою царя.","Від Ідифуна сини Ідифуна: Гедалія, Цері, Ісая, Семей, Хашавія і Маттафія, шестеро, під керівництвом батька свого Ідифуна, який грав на цитрі у славу і хвалу Господа.","Від Емана сини Емана: Буккія, Матфанія, Озиїл, Шевуїл та Ієримоф, Хананія, Ханані, Елиафа, Гиддалті, Ромамті-Езер, Іошбекаша, Маллофі, Гофир і Махазіоф.","Усі ці сини Емана, прозорливця царського, за словами Божими, щоб піднімати славу його. І дав Бог Еману чотирнадцять синів і трьох дочок.","Усі вони під керівництвом батька свого співали в домі Господньому з кимвалами, псалтирями і цитрами при служінні в домі Божому, за вказівкою царя, або Асафа, Ідифуна й Емана.","І було число їх із братами їхніми, навчених співати перед Господом, усіх, що знають цю справу, двісті вісімдесят вісім.","І кинули вони жереб про чергу служіння, малий нарівні з більшим, вчителі нарівні з учнями.","І випав перший жереб Асару для Йосифа; другий Гедалії з братами його і синами його; їх було дванадцять;","третій Заккуру із синами його і братами його; їх — дванадцять;","четвертий Іцрію із синами його і братами його; їх — дванадцять;","п’ятий Нефанії із синами його і братами його; їх — дванадцять;","шостий Буккії із синами його і братами його; їх — дванадцять;","сьомий Ієсареле із синами його і братами його; їх — дванадцять;","восьмий Ісаї із синами його і братами його; їх — дванадцять;","дев’ятий Матфанії із синами його і братами його; їх — дванадцять;","десятий Шимею із синами його і братами його; їх — дванадцять;","одинадцятий Азариїлу із синами його і братами його; їх — дванадцять;","дванадцятий Хашавії із синами його і братами його; їх — дванадцять;","тринадцятий Шуваїлу із синами його і братами його; їх — дванадцять;","чотирнадцятий Маттафії із синами його і братами його; їх — дванадцять;","п’ятнадцятий Ієримофу із синами його і братами його; їх — дванадцять;","шістнадцятий Хананії із синами його і братами його; їх — дванадцять;","сімнадцятий Іошбекаші із синами його і братами його; їх — дванадцять;","вісімнадцятий Ханані із синами його і братами його; їх — дванадцять;","дев’ятнадцятий Маллофію із синами його і братами його; їх — дванадцять;","двадцятий Еліафе із синами його і братами його; їх — дванадцять;","двадцять перший Гофиру із синами його і братами його; їх — дванадцять;","двадцять другий Гиддалтію із синами його і братами його; їх — дванадцять;","двадцять третій Махазіофу із синами його і братами його; їх — дванадцять;","двадцять четвертий Ромамті-Езеру із синами його і братами його; їх — дванадцять."],"x":{"1":"3.4.23|30.47.11|13.5.12","4":"10.16.1","7":"8.10.5","8":"12.24.31"}},{"v":["Ось розподіл воротарів: з кореян: Мешелемія, син Корея, із синів Асафових.","Сини Мешелемії: первісток Захарія, другий Ієдиаїл, третій Зевадія четвертий Іафниїл,","п’ятий Елам, шостий Ієгоханан, сьомий Елиєгоенай.","Сини Овед-Едома: первісток Шемаія, другий Ієгозавад, третій Іоах, четвертий Сахар, п’ятий Нафанаїл,","шостий Аммиїл, сьомий Іссахар, восьмий Пеульфай, тому що Бог благословив його.","У сина його Шемаії народилися також сини, начальники у своєму роді, тому що вони були люди сильні.","Сини Шемаії: Офні, Рефаїл, Овед і Елзавад, брати його, люди сильні, Елія, Семахія [і Ієваком].","Усі вони із синів Овед-Едома; вони і сини їхні, і брати їхні були люди старанні і до служби здібні: їх було в Овед-Едома шістдесят два.","У Мешелемії синів і братів, людей здібних, було вісімнадцять.","У Хоси, із синів Мерариних, сини: Шимрі головний, — хоча він не був первістком, але батько його поставив його головним;","другий Хелкія, третій Тевалія, четвертий Захарія; усіх синів і братів у Хоси було тринадцять.","Ось розподіл воротарів за главами родин, здібних до служби разом із братами їхніми, для служіння в домі Господньому.","І кинули вони жереби, як малий, так і великий, за своїми родинами, на кожні ворота.","І випав жереб на схід Шелемії; і Захарії, синові його, розумному радникові, кинули жереб, і випав йому жереб на північ;","Овед-Едому на південь, а синам його при коморах.","Шупиму і Хосе на захід, біля воріт Шаллехет, де дорога піднімається і де сторожа навпроти сторожі.","На схід по шість левитів, на північ по чотири, на південь по чотири, а при коморах по два.","На захід біля притвору на дорозі по чотири, а біля самого притвору по два.","Ось розподіл воротарів із синів Кореєвих і синів Мерариних.","Левити ж, брати їхні, дивилися за скарбами дому Божого і за скарбницями посвячених речей.","Сини Лаедана, сина Герсонового — від Лаедана, гла́ви родин від Лаедана герсонського: Ієхиїл.","Сини Ієхиїла: Зефам та Іоїль, брат його, дивилися за скарбами дому Господнього,","разом з нащадками Амрама, Іцгара, Хеврона, Озиїла.","Шевуїл, син Гирсона, сина Мойсеєвого, був головним наглядачем за скарбницями.","У брата його Єлиєзера син Рехавія, у нього син Ісая, у нього син Іорам, у нього син Зихрій, у нього син Шеломиф.","Шеломиф і брати його дивилися за всіма скарбницями посвячених речей, які посвятив цар Давид і гла́ви родин і тисячоначальники, стоначальники і проводирі війська.","Із завоювань і зі здобичі вони присвячували на підтримку дому Господнього.","І все, що посвятив Самуїл пророк, і Саул, син Киса, й Авенир, син Нира, й Іоав, син Саруї, усе посвячене було на руках у Шеломифа і братів його.","Із племені Іцгарового: Хенанія і сини його призначені на зовнішнє служіння в ізраїльтян, писарями і суддями.","Із племені Хевронового: Хашавія і брати його, люди мужні, тисяча сімсот, мали нагляд над Ізраїлем по цей бік Йордану на захід, у всяких справах служіння Господнього й у службі царській.","У племені Хевронового Ієрія був главою хевронян, у їхніх родах, у поколіннях. У сороковий рік царювання Давида вони перелічені, і знайдені між ними люди мужні в Іазері галаадському.","І брати його, люди здібні, дві тисячі сімсот, були глави родин. Їх поставив цар Давид над коліном Рувимовим і Гадовим і половиною коліна Манассіїного, в усіх справах Божих і справах царя."],"x":{"1":"25.41.1","13":"12.24.31","20":"10.7.51","21":"12.23.8","24":"12.23.16","26":"10.7.51","27":"3.31.28","28":"8.9.9|12.9.22","31":"12.23.19"}},{"v":["Ось сини Ізраїлеві за числом їх, глави родин, тисячоначальники і стоначальники й управителі, які за відділеннями служили цареві в усіх справах, приходячи і відходячи кожного місяця, в усі місяці року. У кожному відділенні було їх по двадцять чотири тисячі.","Над першим відділенням, у першому місяці, начальствував Іашовам, син Завдиїла; у його відділенні було двадцять чотири тисячі;","він був із синів Фареса, головний над усіма воєначальниками у перший місяць.","Над відділенням другого місяця був Додай ахохиянин; у відділенні його був і князь Миклоф, і в його відділенні було двадцять чотири тисячі.","Третій головний воєначальник, для третього місяця, Ванея, син Іодая, священика, і в його відділенні було двадцять чотири тисячі:","цей Ванея — один із тридцяти хоробрих і начальник над ними, і в його відділенні знаходився Аммизавад, син його.","Четвертий, для четвертого місяця, був Асаїл, брат Іоава, і після нього Завадія, син його, і в його відділенні двадцять чотири тисячі.","П’ятий, для п’ятого місяця, князь Шамгуф ізрахитянин, і в його відділенні двадцять чотири тисячі.","Шостий, для шостого місяця, Іра, син Іккеша, фекоянин, і в його відділенні двадцять чотири тисячі.","Сьомий, для сьомого місяця, Хелец пелонитянин, із синів Єфремових, і в його відділенні двадцять чотири тисячі.","Восьмий, для восьмого місяця, Совохай хушатянин, із племені Зари, і в його відділенні двадцять чотири тисячі.","Дев’ятий, для дев’ятого місяця, Авиєзер анафофянин, із синів Веніамінових, і в його відділенні двадцять чотири тисячі.","Десятий, для десятого місяця, Магарай нетофафянин, із племені Зари, і в його відділенні двадцять чотири тисячі.","Одинадцятий, для одинадцятого місяця, Ванея пирафонянин, із синів Єфремових, і в його відділенні двадцять чотири тисячі.","Дванадцятий, для дванадцятого місяця, Хелдай нетофафянин, з нащадків Гофониїла, і в його відділенні двадцять чотири тисячі.","А над колінами Ізраїлевими, — у рувимлян головним начальником був Єлиєзер, син Зихри; у Симеона — Сафатія, син Маахи;","у Левія — Хашавія, син Кемуїла; в Аарона — Садок;","в Іуди — Елиав, із братів Давида; у Іссахара — Омрі, син Михаїла;","у Завулона–Ішмаія, син Овадії; у Неффалима — Ієримоф, син Азриїла;","у синів Єфремових — Осія, син Азазії; у половини коліна Манассіїного — Іоїль, син Федаії;","у половини коліна Манассії в Галааді — Іддо, син Захарії; у Веніаміна — Іаасиїл, син Авенира;","у Дана — Азариїл, син Ієрохама. Ось вожді колін Ізраїлевих.","Давид не робив переліку тих, які були від двадцяти років і нижче, тому що Господь сказав, що Він примножить Ізраїля, як зірки небесні.","Іоав, син Саруї, почав робити перелік, але не скінчив. І був за це гнів Божий на Ізраїля, і не ввійшов той перелік у літопис царя Давида.","Над скарбами царськими був Азмавеф, син Адиїлів, а над запасами в полі, у містах, і в селах, і у вежах — Іонафан, син Уззії;","над тими, що займаються польовими роботами, землеробством — Езрій, син Хелува;","над виноградниками — Шимей з Рами, а над запасами вина у виноградниках — Завдій із Шефама;","над оливами і смоковницями в долині — Баал Ханаан гедеритянин, а над запасами деревинної олії — Іоас;","над великою худобою, що паслася в Шароні, — Шитрай шаронянин, а над худобою в долинах — Шафат, син Адлая;","над верблюдами — Овил ісмаїльтянин; над ослицями — Ієхдія меронифянин;","над дрібною худобою — Іазиз агаритянин. Усі ці були начальниками над майном, що було в царя Давида.","Іонафан, дядько Давидів, був радником, чоловік розумний і писар; Ієхиїл, син Хахмоніїв, був при синах царя;","Ахитофел був радником царя; Хусій архитянин — другом царя;","після ж Ахитофела Іодай, син Ванеї, та Авиафар, а Іоав був воєначальником у царя."],"x":{"4":"9.23.9|12.11.12","5":"9.23.20","6":"9.23.22","11":"9.21.18","14":"9.23.20:30","15":"9.23.29","23":"3.1.3|0.15.5|0.22.17","24":"12.21.7","29":"31.33.9","32":"9.13.3","33":"9.15.12:37","34":"9.8.16"}},{"v":["І зібрав Давид в Єрусалим усіх вождів ізраїльських, начальників колін і начальників відділень, які служили царю, і тисячоначальників, і стоначальників, і тих, що завідували усім майном і стадами царя і синів його з євнухами, воєначальників і всіх хоробрих мужів.","І став Давид цар на ноги свої і сказав: послухайте мене, брати мої і народ мій! було в мене на серці побудувати дім спокою для ковчега завіту Господнього і для підніжжя ніг Бога нашого, і потрібне для будівлі я приготував.","Але Бог сказав мені: не будуй дому імені Моєму, тому що ти людина войовнича і проливав кров.","Однак же обрав Господь Бог Ізраїлів мене з усього дому батька мого, щоб бути мені царем над Ізраїлем вічно, тому що Іуду обрав Він князем, а в домі Іуди дім батька мого, а із синів батька мого мене благозволив поставити царем над усім Ізраїлем,","з усіх же синів моїх, — тому що багато синів дав мені Господь, — Він обрав Соломона, сина мого, сидіти на престолі царства Господнього над Ізраїлем,","і сказав мені: Соломон, син твій, побудує дім Мій і двори Мої, тому що Я обрав його Собі за сина, і Я буду йому Отцем;","і зміцню царство його повіки, якщо він буде твердий у виконанні заповідей Моїх і уставів Моїх, як до цього дня.","І тепер перед очима всього Ізраїля, зібрання Господнього, й у вуха Бога нашого говорю: дотримуйтесь і тримайтеся всіх заповідей Господа Бога вашого, щоб володіти вам цією доброю землею і залишити її після себе у спадщину дітям своїм навіки;","і ти, Соломоне, сину мій, знай Бога батька твого і служи Йому від усього серця і від усієї душі, тому що Господь випробовує всі серця і знає всі рухи думок. Якщо будеш шукати Його, то знайдеш Його, а якщо залишиш Його, Він залишить тебе назавжди.","Дивися ж, коли Господь обрав тебе побудувати дім для святилища, будь твердий і роби.","І віддав Давид Соломону, синові своєму, креслення притвору і дому його, і комор його, і світлиць його, і внутрішніх покоїв його, і дому для ковчега,","і креслення всього, що було в нього на душі, дворів дому Господнього і всіх кімнат навколо, скарбниць дому Божого і скарбниць речей посвячених,","і священичих і левитських відділень, і всякого службового діла в домі Господньому, і всіх службових сосудів дому Господнього,","золотих речей, із зазначенням ваги, всіх службових сосудів, усіх речей срібних, із зазначенням ваги, для всякого з сосудів службових.","І дав золота для світильників і золотих лампад їх, із зазначенням ваги кожного зі світильників і лампад його, також світильників срібних, із зазначенням ваги кожного світильника і лампад його, зважаючи на службове призначення кожного світильника;","і золота для столів предкладення хлібів, для кожного золотого стола, і срібла для столів срібних,","і виделок, і чаш і кропильниць з чистого золота, і золотих блюд, з зазначенням ваги кожного блюда, і срібних блюд, із зазначенням ваги кожного блюда,","і для жертовника куріння з литого золота із зазначенням ваги, і обладнання колісниці із золотими херувимами, що розпростирають крила і покривають ковчег завіту Господнього.","Усе це написане від Господа, говорив Давид, як Він напоумив мене на всі діла будівництва.","І сказав Давид синові своєму Соломону: будь твердим і мужнім, і приступай до справи, не бійся і не жахайся, тому що Господь Бог, Бог мій, з тобою; Він не відступить від тебе і не залишить тебе, доки не зробиш усієї справи, необхідної для дому Господнього.","І ось відділення священиків і левитів, для всякої служби при домі Божому. І в тебе є для всякої справи старанні люди, майстерні для всякої роботи, і начальники і весь народ готові до всіх твоїх наказів."],"x":{"2":"9.7.2|12.17.1|54.7.46","3":"12.22.8","4":"0.49.8:10|8.16.12","5":"10.3.6|13.1.8|29.9.7","6":"9.7.13|10.5.5|12.17.11","7":"9.7.13|12.17.12","9":"8.16.7|25.7.10|32.11.20|32.17.10|32.20.12|76.2.23","11":"1.25.9","12":"10.6.5","20":"4.31.6|12.22.13|75.13.5"}},{"v":["І сказав цар Давид усьому зібранню: Соломон, син мій, якого одного обрав Бог, молодий і слабосилий, а справа ця велика, тому що не для людини дім це, а для Господа Бога.","Всіма силами я заготував для дому Бога мого золото для золотих речей і срібло для срібних, і мідь для мідних, залізо для залізних, і дерево для дерев’яних, камені онікса і камені вставні, камені красиві і різнобарвні, і всякі дорогі камені, і багато мармуру;","і ще з любови моєї до дому Бога мого, є в мене скарб власний із золота і срібла, і його я віддаю для дому Бога мого, зверх усього, що приготував я для святого дому:","три тисячі талантів золота, золота офирського, і сім тисяч талантів срібла чистого, для обкладання стін у домі,","для кожної із золотих речей, і для кожної зі срібних, і для усякого виробу рук мистецьких. Чи не виявить ревність ще хто жертвувати сьогодні для Господа?","І стали жертвувати начальники родин і начальники колін Ізраїлевих, і начальники тисяч і сотень, і начальники над маєтками царя.","І дали на спорудження дому Божого п’ять тисяч талантів і десять тисяч драхм золота, і срібла десять тисяч талантів, і міді вісімнадцять тисяч талантів, і заліза сто тисяч талантів.","І у кого знайшлися коштовні камені, ті віддавали і їх у скарбницю дому Господнього, на руки Ієхиїлу герсонитянину.","І радів народ ревності їх, тому що вони від усього серця жертвували Господу, також і цар Давид дуже радів.","І благословив Давид Господа перед усім зібранням, і сказав Давид: благословенний Ти, Господи Боже Ізраїля, батька нашого, від віку і до віку!","Твоя, Господи, велич, і могутність, і слава, і перемога і краса, й усе, що на небі і на землі, Твоє: Твоє, Господи, царство, і Ти вище за все, як Владика.","І багатство і слава від лиця Твого, і Ти володарюєш над усім, і в руці Твоїй сила і могутність, і у владі Твоїй звеличувати і зміцнювати усе.","І нині, Боже наш, ми славословимо Тебе і хвалимо величне ім’я Твоє.","Бо хто я і хто народ мій, що ми мали можливість так жертвувати? Але від Тебе все, і від руки Твоєї отримане ми віддали Тобі,","тому що подорожні ми перед Тобою і прибульці, як і всі батьки наші, як тінь дні наші на землі, і немає нічого міцного.","Господи Боже наш! уся ця безліч, що приготували ми для побудови дому Тобі, святому імені Твоєму, від руки Твоєї вона, й усе Твоє.","Знаю, Боже мій, що Ти випробовуєш серце і любиш щире серце: я від щирого серця мого пожертвував усе це, і нині бачу, що і народ Твій, який тут знаходиться, з радістю жертвує Тобі.","Господи, Боже Авраама, Ісаака й Ізраїля, батьків наших! збережи це повік, це виявлення думок серця народу Твого, і направ серце їх до Тебе.","Соломону ж, синові моєму, дай серце праведне, щоб дотримуватися заповідей Твоїх, одкровень Твоїх і уставів Твоїх, і виконати все це і побудувати дім, для якого я зробив приготування.","І сказав Давид усьому зібранню: благословіть Господа Бога нашого. — І благословило все зібрання Господа Бога батьків своїх, і впало, і поклонилося Господу і царю.","І принесли Господу жертви, і піднесли всепалення Господу, на другий після цього день: тисячу тельців, тисячу баранів, тисячу агнців з їх узливаннями, і багато жертв від усього Ізраїля.","І їли і пили перед Господом у той день, з великою радістю; і в другий раз поставили царем Соломона, сина Давидового, і помазали перед Господом на правителя верховного, а Садока на священика.","І сів Соломон на престолі Господньому як цар, замість Давида, батька свого, і був благоуспішним, і весь Ізраїль підкорився йому.","І всі начальники і сильні, також і всі сини царя Давида підкорилися Соломону цареві.","І звеличив Господь Соломона перед очима всього Ізраїля, і дарував йому славу царства, якої не мав раніше нього жоден цар в Ізраїлі.","І Давид, син Ієссеїв, царював над усім Ізраїлем.","Часу царюваня його над Ізраїлем було сорок років: у Хевроні царював він сім років, і в Єрусалимі царював тридцять три роки.","І помер у добрій старості, насичений життям, багатством і славою; і став царем Соломон, син його, замість нього.","Діла царя Давида, перші й останні, описані в записах Самуїла провидця й у записах Нафана пророка й у записах Гада прозорливця,","також і все царювання його, і мужність його, і події, які трапилися з ним і з Ізраїлем і з усіма земними царствами."],"x":{"1":"12.22.5","2":"12.22.14|54.7.46","5":"1.32.29|1.35.5","9":"13.31.8","11":"50.6.13|71.1.17|76.4.10","12":"13.20.6","14":"24.35.7|67.2.13","15":"25.38.13|25.89.9|29.2.5","17":"12.28.9|54.1.24","18":"1.3.6|1.4.5","22":"10.1.33","23":"10.2.12","25":"10.3.13","26":"10.2.11","27":"9.5.5","28":"0.25.8"}}];
export default C;
